// Generated by tests/compile_revised_tests.py; retain both published editions.
(function(){const d=window.L4_TEST_DATA;if(!d||d.revision!=="2026-11-12-tests-1"||d.tests.length!==50)throw Error("Original test edition incomplete");d.editions={[d.revision]:d.tests.slice()};d.tests=d.tests.slice(0,10);d.revision="2026-11-12-tests-2";d.revisedPackSha256={};d.editions[d.revision]=d.tests;d.tests.push(...[{"id":"T11","title":"K1 · Current & Relevant Data Legislation","description":"Purpose, legal principles, access, retention and accountable handling.","questions":[{"ksb":"K1","objective":"Aggregate release","prompt":"A report removes names but includes a single person in one rare postcode-age group. Which checks are needed before calling the output anonymous?","options":[{"text":"Assess the table in isolation from all other available information","why":"The release context and plausible linkage affect identifiability.","correct":false,"id":"A"},{"text":"Assess whether the small group can identify someone","why":"A rare combination can identify an individual even without a name field.","correct":true,"id":"B"},{"text":"Apply suitable aggregation or suppression and reassess utility","why":"Disclosure treatment must address the identifying combination; removing one label may leave the person identifiable.","correct":true,"id":"C"},{"text":"Conclude that absence of names settles anonymity","why":"A rare combination can identify an individual even without a name field.","correct":false,"id":"D"},{"text":"Assume a public-service purpose makes identification harmless","why":"Purpose and audience affect risk assessment but do not themselves establish anonymity.","correct":false,"id":"E"},{"text":"Consider linkage to information available to recipients","why":"The release context and plausible linkage affect identifiability.","correct":true,"id":"F"},{"text":"Remove only the postcode label while retaining the rare record's other details","why":"Disclosure treatment must address the identifying combination; removing one label may leave the person identifiable.","correct":false,"id":"G"},{"text":"Assume an internal audience automatically makes the output anonymous","why":"Purpose and audience affect risk assessment but do not themselves establish anonymity.","correct":false,"id":"H"}],"answer":"A rare combination can identify an individual even without a name field. The release context and plausible linkage affect identifiability. Disclosure treatment must address the identifying combination; removing one label may leave the person identifiable. Purpose and audience affect risk assessment but do not themselves establish anonymity.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q01"},{"ksb":"K1","objective":"Retention decisions","prompt":"A project has ended. Its identifiable working extract is covered by a retention schedule, but the team proposes keeping it indefinitely for reproducibility. Which actions are justified?","options":[{"text":"Delete only your laptop copy and declare the extract removed","why":"Copies in shared locations also need consideration within the authorised retention and disposal process.","correct":false,"id":"A"},{"text":"Treat useful analytical code as permission to retain every underlying record","why":"Reusable code and retained personal data have different needs; continued retention needs justification.","correct":false,"id":"B"},{"text":"Retain suitable methods and non-identifying audit material where allowed","why":"Appropriate methodological records can support reproducibility without automatically retaining every identifiable copy.","correct":true,"id":"C"},{"text":"Check the applicable schedule and any authorised hold","why":"Retention depends on the applicable purpose, policy and obligations, rather than an invented universal duration.","correct":true,"id":"D"},{"text":"Preserve all identifiable snapshots because methods were complex","why":"Appropriate methodological records can support reproducibility without automatically retaining every identifiable copy.","correct":false,"id":"E"},{"text":"Seek a justified approval if continued retention is needed","why":"Reusable code and retained personal data have different needs; continued retention needs justification.","correct":true,"id":"F"},{"text":"Include shared working copies in the disposal process","why":"Copies in shared locations also need consideration within the authorised retention and disposal process.","correct":true,"id":"G"},{"text":"Apply a universal seven-year period to every project file","why":"Retention depends on the applicable purpose, policy and obligations, rather than an invented universal duration.","correct":false,"id":"H"}],"answer":"Retention depends on the applicable purpose, policy and obligations, rather than an invented universal duration. Reusable code and retained personal data have different needs; continued retention needs justification. Appropriate methodological records can support reproducibility without automatically retaining every identifiable copy. Copies in shared locations also need consideration within the authorised retention and disposal process.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q02"},{"ksb":"K1","objective":"Data minimisation","prompt":"A weekly dashboard needs counts by service and month. The proposed extract also includes names, full addresses and clinical notes. Which changes apply minimisation without losing the agreed measure?","options":[{"text":"Retain notes because a future project might need them","why":"Speculative future utility does not demonstrate necessity for this dashboard's purpose.","correct":false,"id":"A"},{"text":"Define necessary fields by whichever columns the export includes","why":"A purpose-to-field justification supports accountability; the source export's convenience is not the requirement.","correct":false,"id":"B"},{"text":"Keep names in a hidden report tab for possible later use","why":"Hidden tabs still retain information; names are unnecessary for the stated aggregate measure.","correct":false,"id":"C"},{"text":"Aggregate to the required service-month level","why":"Aggregation can meet the agreed measure while reducing unnecessary detail, subject to disclosure checks.","correct":true,"id":"D"},{"text":"Document the required fields against the reporting purpose","why":"A purpose-to-field justification supports accountability; the source export's convenience is not the requirement.","correct":true,"id":"E"},{"text":"Exclude clinical notes from this reporting workflow","why":"Speculative future utility does not demonstrate necessity for this dashboard's purpose.","correct":true,"id":"F"},{"text":"Supply individual records because the counts can be calculated later","why":"Aggregation can meet the agreed measure while reducing unnecessary detail, subject to disclosure checks.","correct":false,"id":"G"},{"text":"Remove direct identifiers from the dashboard extract","why":"Hidden tabs still retain information; names are unnecessary for the stated aggregate measure.","correct":true,"id":"H"}],"answer":"Hidden tabs still retain information; names are unnecessary for the stated aggregate measure. Speculative future utility does not demonstrate necessity for this dashboard's purpose. Aggregation can meet the agreed measure while reducing unnecessary detail, subject to disclosure checks. A purpose-to-field justification supports accountability; the source export's convenience is not the requirement.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q03"},{"ksb":"K1","objective":"Accountability","prompt":"An assessor asks how your project showed accountability. You have an access approval, a purpose record and a documented retention decision. Which explanations use this material appropriately?","options":[{"text":"Explain the purpose record and responsibility for decisions","why":"An access approval addresses one control; accountability also needs a reasoned account of purpose, retention and other relevant requirements.","correct":true,"id":"A"},{"text":"Replace the records with an unsupported statement that the organisation is compliant","why":"Suitable protected evidence and explanation are preferable to either unnecessary disclosure or unsupported assurance.","correct":false,"id":"B"},{"text":"State that retention was irrelevant because the final report was aggregate","why":"Personal working copies can remain relevant even when the final output contains aggregates.","correct":false,"id":"C"},{"text":"Connect the access approval to the data you actually used","why":"Access approval supports a particular control; it is not universal proof of legal compliance.","correct":true,"id":"D"},{"text":"Use the access approval alone to demonstrate compliance with every data-protection principle","why":"An access approval addresses one control; accountability also needs a reasoned account of purpose, retention and other relevant requirements.","correct":false,"id":"E"},{"text":"Claim the approval proves compliance with every principle","why":"Access approval supports a particular control; it is not universal proof of legal compliance.","correct":false,"id":"F"},{"text":"Publish the full unredacted approval trail as the only acceptable evidence","why":"Suitable protected evidence and explanation are preferable to either unnecessary disclosure or unsupported assurance.","correct":false,"id":"G"},{"text":"Explain how the retention decision affected working copies","why":"Personal working copies can remain relevant even when the final output contains aggregates.","correct":true,"id":"H"}],"answer":"Access approval supports a particular control; it is not universal proof of legal compliance. An access approval addresses one control; accountability also needs a reasoned account of purpose, retention and other relevant requirements. Personal working copies can remain relevant even when the final output contains aggregates. Suitable protected evidence and explanation are preferable to either unnecessary disclosure or unsupported assurance.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q04"},{"ksb":"K1","objective":"Pseudonymisation","prompt":"Names are replaced with random identifiers. A separately controlled lookup still connects identifiers to people. Which conclusions follow?","options":[{"text":"Classify the extract as anonymous because the linkage table is held by a different team","why":"Separating and controlling a usable linkage reduces access risk but does not by itself turn pseudonymised data into anonymous data.","correct":false,"id":"A"},{"text":"Give every dashboard viewer the lookup for transparency","why":"Broadly distributing the linkage undermines the separation that reduces identification risk.","correct":false,"id":"B"},{"text":"Restrict access to the lookup according to need","why":"Broadly distributing the linkage undermines the separation that reduces identification risk.","correct":true,"id":"C"},{"text":"Publish the lookup separately and call both files anonymous","why":"Publishing a linkage does not anonymise the data, and pseudonymisation does not by itself remove retention obligations.","correct":false,"id":"D"},{"text":"Assess linkage and indirect identifiers in the release context","why":"Identifiability can depend on combinations and available auxiliary information, not just direct names.","correct":true,"id":"E"},{"text":"The transformed records may still be personal data","why":"Separating and controlling a usable linkage reduces access risk but does not by itself turn pseudonymised data into anonymous data.","correct":true,"id":"F"},{"text":"Exclude the records from retention controls because names were removed","why":"Publishing a linkage does not anonymise the data, and pseudonymisation does not by itself remove retention obligations.","correct":false,"id":"G"},{"text":"Assess anonymity only by searching for name columns","why":"Identifiability can depend on combinations and available auxiliary information, not just direct names.","correct":false,"id":"H"}],"answer":"Separating and controlling a usable linkage reduces access risk but does not by itself turn pseudonymised data into anonymous data. Broadly distributing the linkage undermines the separation that reduces identification risk. Identifiability can depend on combinations and available auxiliary information, not just direct names. Publishing a linkage does not anonymise the data, and pseudonymisation does not by itself remove retention obligations.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q05"},{"ksb":"K1","objective":"Accuracy disputes","prompt":"A service user challenges an address used in your analysis. The source owner has not yet verified the correct address. Which responses support the accuracy principle?","options":[{"text":"Assume a recently updated address cannot be wrong","why":"Format validity and recent modification do not establish that an address reflects reality.","correct":false,"id":"A"},{"text":"Replace the address with your best guess immediately","why":"A flagged investigation preserves uncertainty; a guess creates another unsupported value.","correct":false,"id":"B"},{"text":"Record the decision and affected analytical outputs","why":"An appropriate record helps explain the correction and identify outputs requiring review.","correct":true,"id":"C"},{"text":"Delete the correction trail once the dashboard refreshes","why":"An appropriate record helps explain the correction and identify outputs requiring review.","correct":false,"id":"D"},{"text":"Assume a valid postcode proves the whole address is accurate","why":"Format validity and recent modification do not establish that an address reflects reality.","correct":false,"id":"E"},{"text":"Follow the authorised correction process","why":"Correcting a displayed label does not resolve the disputed source value through its responsible process.","correct":true,"id":"F"},{"text":"Edit only the chart label and treat the source as corrected","why":"Correcting a displayed label does not resolve the disputed source value through its responsible process.","correct":false,"id":"G"},{"text":"Flag the disputed record while the owner investigates","why":"A flagged investigation preserves uncertainty; a guess creates another unsupported value.","correct":true,"id":"H"}],"answer":"A flagged investigation preserves uncertainty; a guess creates another unsupported value. Correcting a displayed label does not resolve the disputed source value through its responsible process. An appropriate record helps explain the correction and identify outputs requiring review. Format validity and recent modification do not establish that an address reflects reality.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q06"},{"ksb":"K1","objective":"Legal basis and consent","prompt":"A proposed public-service analysis uses personal records. A colleague asks every subject for consent before anyone has established the appropriate legal basis. Which advice is sound?","options":[{"text":"Omit transparency information if another lawful basis applies","why":"Using a basis other than consent does not remove relevant transparency responsibilities.","correct":false,"id":"A"},{"text":"Record the access approval as a substitute for documenting the lawful-basis assessment","why":"Access permission and the justification for using personal data answer different questions; accountability needs the relevant reasoning about the proposed use.","correct":false,"id":"B"},{"text":"Record the basis and reasoning through the agreed process","why":"Access permission and the justification for using personal data answer different questions; accountability needs the relevant reasoning about the proposed use.","correct":true,"id":"C"},{"text":"Establish the appropriate basis with the responsible role first","why":"The appropriate legal basis depends on the processing context; consent is not universally mandatory.","correct":true,"id":"D"},{"text":"Explain the purpose and relevant processing information clearly","why":"Using a basis other than consent does not remove relevant transparency responsibilities.","correct":true,"id":"E"},{"text":"Infer valid consent from a person's failure to complain","why":"Silence does not establish the informed, meaningful agreement required where consent is relied upon.","correct":false,"id":"F"},{"text":"Assume consent must be the basis for every analysis","why":"The appropriate legal basis depends on the processing context; consent is not universally mandatory.","correct":false,"id":"G"},{"text":"Check whether consent would be meaningful in this relationship","why":"Silence does not establish the informed, meaningful agreement required where consent is relied upon.","correct":true,"id":"H"}],"answer":"The appropriate legal basis depends on the processing context; consent is not universally mandatory. Silence does not establish the informed, meaningful agreement required where consent is relied upon. Using a basis other than consent does not remove relevant transparency responsibilities. Access permission and the justification for using personal data answer different questions; accountability needs the relevant reasoning about the proposed use.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q07"},{"ksb":"K1","objective":"Secondary use","prompt":"A service team wants to use identifiable appointment records for an unrelated marketing campaign. Which steps address whether that reuse is permitted?","options":[{"text":"Ask the campaign sponsor alone to waive the purpose restriction","why":"The sponsor's commercial objective does not replace the organisation's responsible privacy review.","correct":false,"id":"A"},{"text":"Remove names but retain linkable customer IDs and assume laws no longer apply","why":"Encryption and pseudonymisation can reduce risk, but neither authorises the new purpose or necessarily removes personal-data status.","correct":false,"id":"B"},{"text":"Encrypt the extract and assume reuse is then permitted","why":"Encryption and pseudonymisation can reduce risk, but neither authorises the new purpose or necessarily removes personal-data status.","correct":false,"id":"C"},{"text":"Refer unresolved compatibility questions to the responsible privacy role","why":"The sponsor's commercial objective does not replace the organisation's responsible privacy review.","correct":true,"id":"D"},{"text":"Treat the notice covering appointment administration as sufficient transparency for the marketing campaign","why":"A notice for the original service purpose does not automatically explain an unrelated marketing use; its actual wording and reasonable expectations need assessment.","correct":false,"id":"E"},{"text":"Check what people were told about their information","why":"A notice for the original service purpose does not automatically explain an unrelated marketing use; its actual wording and reasonable expectations need assessment.","correct":true,"id":"F"},{"text":"Treat the existing database login as reuse approval","why":"Access permission concerns entry to a system; the new purpose still needs an appropriate legal assessment.","correct":false,"id":"G"},{"text":"Assess the proposed purpose and applicable lawful basis","why":"Access permission concerns entry to a system; the new purpose still needs an appropriate legal assessment.","correct":true,"id":"H"}],"answer":"Access permission concerns entry to a system; the new purpose still needs an appropriate legal assessment. A notice for the original service purpose does not automatically explain an unrelated marketing use; its actual wording and reasonable expectations need assessment. The sponsor's commercial objective does not replace the organisation's responsible privacy review. Encryption and pseudonymisation can reduce risk, but neither authorises the new purpose or necessarily removes personal-data status.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q08"},{"ksb":"K1","objective":"First principle","prompt":"A colleague says, 'Our processing is lawful, so the first UK GDPR principle is satisfied.' Which additions make that explanation complete?","options":[{"text":"Count accuracy as a substitute for fairness","why":"Accuracy and security are important principles, but they do not replace the fairness and transparency components.","correct":false,"id":"A"},{"text":"Explain how the use is made transparent","why":"Transparency concerns understandable information about processing, not unrestricted system access.","correct":true,"id":"B"},{"text":"Explain why the identified legal basis fits this purpose","why":"A technical account does not establish the lawful basis for the actual processing.","correct":true,"id":"C"},{"text":"Replace fairness with the project's estimated cost saving","why":"A benefit to the organisation does not itself establish fair treatment of people.","correct":false,"id":"D"},{"text":"Count encryption as a substitute for transparency","why":"Accuracy and security are important principles, but they do not replace the fairness and transparency components.","correct":false,"id":"E"},{"text":"Cite the existence of a company account as the legal basis","why":"A technical account does not establish the lawful basis for the actual processing.","correct":false,"id":"F"},{"text":"Equate transparency with giving analysts unrestricted access","why":"Transparency concerns understandable information about processing, not unrestricted system access.","correct":false,"id":"G"},{"text":"Explain fairness to the affected people","why":"A benefit to the organisation does not itself establish fair treatment of people.","correct":true,"id":"H"}],"answer":"A benefit to the organisation does not itself establish fair treatment of people. Transparency concerns understandable information about processing, not unrestricted system access. A technical account does not establish the lawful basis for the actual processing. Accuracy and security are important principles, but they do not replace the fairness and transparency components.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q09"},{"ksb":"K1","objective":"Disclosure incident","prompt":"An identifiable extract has been sent to an unintended recipient. You do not know whether it was opened. Which initial actions fit secure, accountable handling?","options":[{"text":"Record what was sent, when and to whom using approved channels","why":"A factual, controlled report supports assessment without unnecessarily expanding the disclosure.","correct":true,"id":"A"},{"text":"Circulate the extract widely so colleagues can assess the incident","why":"A factual, controlled report supports assessment without unnecessarily expanding the disclosure.","correct":false,"id":"B"},{"text":"Follow authorised containment instructions and preserve relevant facts","why":"Containment should support investigation, not destroy the record of what occurred.","correct":true,"id":"C"},{"text":"Let responsible roles assess external reporting obligations","why":"Reporting obligations depend on the assessed circumstances and the relevant responsible process.","correct":true,"id":"D"},{"text":"Announce that every mistaken email automatically has the same reporting outcome","why":"Reporting obligations depend on the assessed circumstances and the relevant responsible process.","correct":false,"id":"E"},{"text":"Follow the internal incident-reporting route promptly","why":"Uncertainty about access should be reported through the relevant process rather than used to delay it.","correct":true,"id":"F"},{"text":"Wait for proof of harm before informing the responsible team","why":"Uncertainty about access should be reported through the relevant process rather than used to delay it.","correct":false,"id":"G"},{"text":"Delete your message history before the incident can be investigated","why":"Containment should support investigation, not destroy the record of what occurred.","correct":false,"id":"H"}],"answer":"Uncertainty about access should be reported through the relevant process rather than used to delay it. Containment should support investigation, not destroy the record of what occurred. Reporting obligations depend on the assessed circumstances and the relevant responsible process. A factual, controlled report supports assessment without unnecessarily expanding the disclosure.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."},"id":"T11-E2-Q10"}]},{"id":"T12","title":"K2 · Organisational Data Policies & Standards","description":"Actual policies, procedures, standards, approvals and AI use.","questions":[{"ksb":"K2","objective":"Non-compliance impact","prompt":"A restricted spreadsheet is shared too broadly inside the organisation. No external publication occurred. Which consequences should an explanation consider?","options":[{"text":"Damage to trust and possible organisational consequences","why":"Internal access does not automatically remove policy, trust or other relevant consequences.","correct":true,"id":"A"},{"text":"Assume an internal recipient makes policy consequences impossible","why":"Internal access does not automatically remove policy, trust or other relevant consequences.","correct":false,"id":"B"},{"text":"Declare a specific fine without an assessed legal finding","why":"The facts need assessment; neither an invented sanction nor absence of complaints settles impact.","correct":false,"id":"C"},{"text":"Conclude no consequence exists until someone complains","why":"The facts need assessment; neither an invented sanction nor absence of complaints settles impact.","correct":false,"id":"D"},{"text":"Potential harm from inappropriate internal access","why":"An internal disclosure can still affect confidentiality and people.","correct":true,"id":"E"},{"text":"Investigation and remediation effort","why":"Remediation can consume time and interrupt services beyond the initial task.","correct":true,"id":"F"},{"text":"Limit the assessment to whether the file reached the internet","why":"An internal disclosure can still affect confidentiality and people.","correct":false,"id":"G"},{"text":"Count only the original extraction time as the operational cost","why":"Remediation can consume time and interrupt services beyond the initial task.","correct":false,"id":"H"}],"answer":"An internal disclosure can still affect confidentiality and people. Remediation can consume time and interrupt services beyond the initial task. Internal access does not automatically remove policy, trust or other relevant consequences. The facts need assessment; neither an invented sanction nor absence of complaints settles impact.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q01"},{"ksb":"K2","objective":"Policy versus procedure","prompt":"A policy requires restricted sharing, a standard specifies approved encryption, and a procedure explains the transfer steps. Which distinctions are correct?","options":[{"text":"Explain how the three documents work together in this transfer","why":"The transfer needs the applicable rule, protection standard and operational process together.","correct":true,"id":"A"},{"text":"Treat following one document as evidence that the others are irrelevant","why":"The transfer needs the applicable rule, protection standard and operational process together.","correct":false,"id":"B"},{"text":"The policy is simply the screen-by-screen transfer guide","why":"A governing rule and the practical sequence used to follow it have different roles.","correct":false,"id":"C"},{"text":"The procedure describes how to perform the approved transfer","why":"Practical steps implement the rule; they do not automatically override it.","correct":true,"id":"D"},{"text":"The procedure grants an exception to the policy by itself","why":"Practical steps implement the rule; they do not automatically override it.","correct":false,"id":"E"},{"text":"The standard is an optional personal preference","why":"In this example the standard defines a required protection expectation.","correct":false,"id":"F"},{"text":"The standard specifies the required protection level","why":"In this example the standard defines a required protection expectation.","correct":true,"id":"G"},{"text":"The policy states the governing sharing rule","why":"A governing rule and the practical sequence used to follow it have different roles.","correct":true,"id":"H"}],"answer":"A governing rule and the practical sequence used to follow it have different roles. In this example the standard defines a required protection expectation. Practical steps implement the rule; they do not automatically override it. The transfer needs the applicable rule, protection standard and operational process together.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q02"},{"ksb":"K2","objective":"Policy change","prompt":"Mid-project, the approved retention policy changes and specifies when existing projects must adopt it. Which actions are appropriate?","options":[{"text":"Promise no impact before reviewing working copies","why":"The practical consequences need assessment before giving assurance.","correct":false,"id":"A"},{"text":"Assume all existing projects are permanently exempt","why":"Applicability to ongoing work depends on the actual transition rule.","correct":false,"id":"B"},{"text":"Check the transition provisions for this project","why":"Applicability to ongoing work depends on the actual transition rule.","correct":true,"id":"C"},{"text":"Apply the new rule only to the final presentation slide","why":"Retention rules affect stored information and processes, not just report wording.","correct":false,"id":"D"},{"text":"Review affected extracts and scheduled deletion tasks","why":"Retention rules affect stored information and processes, not just report wording.","correct":true,"id":"E"},{"text":"Agree and record necessary changes with responsible owners","why":"Coordinated, authorised changes make the impact and responsibilities clear.","correct":true,"id":"F"},{"text":"Change retention dates silently without checking authority","why":"Coordinated, authorised changes make the impact and responsibilities clear.","correct":false,"id":"G"},{"text":"Communicate any delivery or reproducibility implications","why":"The practical consequences need assessment before giving assurance.","correct":true,"id":"H"}],"answer":"Applicability to ongoing work depends on the actual transition rule. Retention rules affect stored information and processes, not just report wording. Coordinated, authorised changes make the impact and responsibilities clear. The practical consequences need assessment before giving assurance.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q03"},{"ksb":"K2","objective":"Classification mismatch","prompt":"A project brief labels a file public, but the approved handling catalogue lists the source as restricted. Which actions resolve this responsibly?","options":[{"text":"Pause sharing while the classification is clarified","why":"Project-specific wording does not automatically override the authoritative handling scheme.","correct":true,"id":"A"},{"text":"Keep both labels without explaining which controls apply","why":"A documented resolution lets the team apply consistent handling.","correct":false,"id":"B"},{"text":"Treat the correction as a label-only change","why":"A changed treatment can require practical review of access and stored copies.","correct":false,"id":"C"},{"text":"Prefer the brief because it was written for this project","why":"Project-specific wording does not automatically override the authoritative handling scheme.","correct":false,"id":"D"},{"text":"Consult the classification owner using the agreed route","why":"Classification needs the relevant authority and criteria, not audience convenience.","correct":true,"id":"E"},{"text":"Ask the report's audience to choose the least restrictive label","why":"Classification needs the relevant authority and criteria, not audience convenience.","correct":false,"id":"F"},{"text":"Check existing copies and permissions against the confirmed treatment","why":"A changed treatment can require practical review of access and stored copies.","correct":true,"id":"G"},{"text":"Record the confirmed treatment and update affected plans","why":"A documented resolution lets the team apply consistent handling.","correct":true,"id":"H"}],"answer":"Project-specific wording does not automatically override the authoritative handling scheme. Classification needs the relevant authority and criteria, not audience convenience. A documented resolution lets the team apply consistent handling. A changed treatment can require practical review of access and stored copies.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q04"},{"ksb":"K2","objective":"AI handling rules","prompt":"You want an external AI service to summarise a confidential extract. The organisation's guidance permits only approved tools and specified data categories. Which actions fit the guidance?","options":[{"text":"Check approval for both the tool and intended data use","why":"A subscription alone does not establish permission for the tool or the confidential data.","correct":true,"id":"A"},{"text":"Assume a paid service guarantees the required handling terms","why":"Partial redaction and payment do not establish compliance with the organisation's specific AI conditions.","correct":false,"id":"B"},{"text":"Treat a colleague's personal subscription as organisational approval","why":"A subscription alone does not establish permission for the tool or the confidential data.","correct":false,"id":"C"},{"text":"Use an authorised alternative if this use is not permitted","why":"A useful result does not justify bypassing the prior handling requirements.","correct":true,"id":"D"},{"text":"Treat internal sharing permission as approval for the external AI service","why":"Permission for internal sharing does not establish approval for a different external processing service.","correct":false,"id":"E"},{"text":"Consult the responsible owner about an uncertain category","why":"Permission for internal sharing does not establish approval for a different external processing service.","correct":true,"id":"F"},{"text":"Upload first and seek retrospective approval if the result is useful","why":"A useful result does not justify bypassing the prior handling requirements.","correct":false,"id":"G"},{"text":"Assume removing the company name satisfies every AI rule","why":"Partial redaction and payment do not establish compliance with the organisation's specific AI conditions.","correct":false,"id":"H"}],"answer":"A subscription alone does not establish permission for the tool or the confidential data. A useful result does not justify bypassing the prior handling requirements. Permission for internal sharing does not establish approval for a different external processing service. Partial redaction and payment do not establish compliance with the organisation's specific AI conditions.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q05"},{"ksb":"K2","objective":"Conflicting instructions","prompt":"A manager asks you to send a restricted extract through a channel prohibited by policy. The approved channel is temporarily unavailable. Which next steps are justified?","options":[{"text":"Seek an approved alternative or formal exception route","why":"Similar technical features do not establish organisational approval.","correct":true,"id":"A"},{"text":"Record the prohibited transfer as compliant because it was temporary","why":"A truthful revised plan is preferable to relabelling a prohibited action.","correct":false,"id":"B"},{"text":"Encrypt the attachment and assume the prohibited channel is now approved","why":"Useful safeguards do not by themselves override the stated channel restriction; an authorised route or exception is still needed.","correct":false,"id":"C"},{"text":"Treat a manager's urgency as automatic policy approval","why":"Urgency does not itself create an authorised exception.","correct":false,"id":"D"},{"text":"Explain the policy conflict and delivery constraint","why":"Urgency does not itself create an authorised exception.","correct":true,"id":"E"},{"text":"Agree a revised delivery plan if no compliant route exists","why":"A truthful revised plan is preferable to relabelling a prohibited action.","correct":true,"id":"F"},{"text":"Remove direct names and assume the remaining restricted extract may use that channel","why":"Useful safeguards do not by themselves override the stated channel restriction; an authorised route or exception is still needed.","correct":false,"id":"G"},{"text":"Select a consumer transfer site with similar encryption","why":"Similar technical features do not establish organisational approval.","correct":false,"id":"H"}],"answer":"Urgency does not itself create an authorised exception. Similar technical features do not establish organisational approval. A truthful revised plan is preferable to relabelling a prohibited action. Useful safeguards do not by themselves override the stated channel restriction; an authorised route or exception is still needed.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q06"},{"ksb":"K2","objective":"Storage rules","prompt":"A policy allows this dataset only in a managed project workspace. A personal cloud drive offers easier sharing. Which decisions follow from the rule?","options":[{"text":"Keep working copies in the approved workspace","why":"A password does not make an unapproved storage location compliant with the stated rule.","correct":true,"id":"A"},{"text":"Use permitted sharing controls for intended recipients","why":"Approved storage does not remove the need to control its sharing permissions.","correct":true,"id":"B"},{"text":"Treat inconvenience as an implied storage exemption","why":"A workflow constraint should be addressed through the responsible route rather than an invented exception.","correct":false,"id":"C"},{"text":"Put the extract in a personal email draft instead of a cloud folder","why":"Temporary copies and email drafts still use locations outside the permitted workspace.","correct":false,"id":"D"},{"text":"Create an unrestricted link because the file is already in managed storage","why":"Approved storage does not remove the need to control its sharing permissions.","correct":false,"id":"E"},{"text":"Store the file personally but delete it after the meeting","why":"Temporary copies and email drafts still use locations outside the permitted workspace.","correct":false,"id":"F"},{"text":"Move a copy to personal storage if access is password protected","why":"A password does not make an unapproved storage location compliant with the stated rule.","correct":false,"id":"G"},{"text":"Raise missing collaboration features with the workspace owner","why":"A workflow constraint should be addressed through the responsible route rather than an invented exception.","correct":true,"id":"H"}],"answer":"A password does not make an unapproved storage location compliant with the stated rule. Approved storage does not remove the need to control its sharing permissions. A workflow constraint should be addressed through the responsible route rather than an invented exception. Temporary copies and email drafts still use locations outside the permitted workspace.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q07"},{"ksb":"K2","objective":"Policy versions","prompt":"You find two retention policies: an old PDF in a team folder and a newer copy on the controlled policy site. Which steps establish the rule to use?","options":[{"text":"Check whether the policy covers this dataset and project","why":"Applicability matters; picking a number without its scope can misapply the rule.","correct":true,"id":"A"},{"text":"Average the two retention periods","why":"Neither averaging documents nor tool preference resolves a policy-version conflict.","correct":false,"id":"B"},{"text":"Verify the current approved version with its owner","why":"Familiarity does not establish currency; controlled approval and ownership provide stronger evidence.","correct":true,"id":"C"},{"text":"Apply the shortest period mentioned anywhere in either document","why":"Applicability matters; picking a number without its scope can misapply the rule.","correct":false,"id":"D"},{"text":"Cite only the policy's title without checking its content","why":"A traceable requirement explains how the actual rule shaped the work.","correct":false,"id":"E"},{"text":"Let your preferred analytical tool determine retention","why":"Neither averaging documents nor tool preference resolves a policy-version conflict.","correct":false,"id":"F"},{"text":"Choose the PDF colleagues have used longest","why":"Familiarity does not establish currency; controlled approval and ownership provide stronger evidence.","correct":false,"id":"G"},{"text":"Record the source and relevant requirement in your project notes","why":"A traceable requirement explains how the actual rule shaped the work.","correct":true,"id":"H"}],"answer":"Familiarity does not establish currency; controlled approval and ownership provide stronger evidence. Applicability matters; picking a number without its scope can misapply the rule. A traceable requirement explains how the actual rule shaped the work. Neither averaging documents nor tool preference resolves a policy-version conflict.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q08"},{"ksb":"K2","objective":"Daily application","prompt":"Your employer requires approved accounts, restricted exports and an incident process. Which portfolio details demonstrate how those rules affected your own work?","options":[{"text":"Paste the entire policy without relating it to the dataset","why":"A reasoned field decision shows application beyond reproducing policy text.","correct":false,"id":"A"},{"text":"Describe the access role used for the extraction","why":"A specific control connects the policy to your actual activity.","correct":true,"id":"B"},{"text":"Invent a security incident to make the example stronger","why":"A truthful explanation can show the relevant route without claiming an event that did not occur.","correct":false,"id":"C"},{"text":"State only that the organisation takes security seriously","why":"A specific control connects the policy to your actual activity.","correct":false,"id":"D"},{"text":"Explain which fields you excluded under the export rule","why":"A reasoned field decision shows application beyond reproducing policy text.","correct":true,"id":"E"},{"text":"Claim responsibility for all company security operations","why":"The account should distinguish your work from wider organisational or colleague responsibilities.","correct":false,"id":"F"},{"text":"Describe the escalation route you would use for an uncertainty","why":"A truthful explanation can show the relevant route without claiming an event that did not occur.","correct":true,"id":"G"},{"text":"Attribute a colleague's access review to your own actions","why":"The account should distinguish your work from wider organisational or colleague responsibilities.","correct":false,"id":"H"}],"answer":"A specific control connects the policy to your actual activity. A reasoned field decision shows application beyond reproducing policy text. A truthful explanation can show the relevant route without claiming an event that did not occur. The account should distinguish your work from wider organisational or colleague responsibilities.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q09"},{"ksb":"K2","objective":"Access exceptions","prompt":"Your report deadline precedes an access review. A colleague offers to run unrestricted queries using their account. Which responses respect the stated access-control policy?","options":[{"text":"Borrow the colleague's login for a single extraction","why":"Sharing credentials bypasses the identity and authorisation controls being reviewed.","correct":false,"id":"A"},{"text":"Treat any extract a colleague can produce as approved for your use","why":"Another person's access does not establish your permission to receive or use the output.","correct":false,"id":"B"},{"text":"Request the necessary access through the approved route","why":"Sharing credentials bypasses the identity and authorisation controls being reviewed.","correct":true,"id":"C"},{"text":"Discuss a permitted, appropriately limited interim output","why":"Another person's access does not establish your permission to receive or use the output.","correct":true,"id":"D"},{"text":"Describe an informal chat as an approved policy exception","why":"An exception must follow the actual authority and process specified by the organisation.","correct":false,"id":"E"},{"text":"Record an authorised exception if the policy provides that route","why":"An exception must follow the actual authority and process specified by the organisation.","correct":true,"id":"F"},{"text":"Tell the sponsor how the access dependency affects delivery","why":"Communicating the constraint enables a realistic, compliant delivery decision.","correct":true,"id":"G"},{"text":"Conceal the dependency and promise the unchanged delivery date","why":"Communicating the constraint enables a realistic, compliant delivery decision.","correct":false,"id":"H"}],"answer":"Sharing credentials bypasses the identity and authorisation controls being reviewed. Another person's access does not establish your permission to receive or use the output. Communicating the constraint enables a realistic, compliant delivery decision. An exception must follow the actual authority and process specified by the organisation.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T12-E2-Q10"}]},{"id":"T13","title":"K3 · Principles of the Data Analysis Lifecycle","description":"Lifecycle stages, iteration, checks and communication.","questions":[{"ksb":"K3","objective":"Refining a result","prompt":"A first dashboard shows an implausible increase after joining a reference table. Which refining activities are appropriate?","options":[{"text":"Assume the query is correct because it executed","why":"Successful execution does not establish the intended join cardinality or meaning.","correct":false,"id":"A"},{"text":"Revisit preparation if the reference table needs authorised correction","why":"Refinement can legitimately send the work back to an earlier stage.","correct":true,"id":"B"},{"text":"Remove repeated displayed totals without investigating the joined rows","why":"A display-level change can conceal the symptom while the underlying join still multiplies records.","correct":false,"id":"C"},{"text":"Compare the corrected output against the source totals","why":"Independent reconciliation provides stronger support than a plausible appearance.","correct":true,"id":"D"},{"text":"Investigate duplicate lookup keys and unmatched records","why":"Successful execution does not establish the intended join cardinality or meaning.","correct":true,"id":"E"},{"text":"Reconcile row counts before and after the join","why":"A display-level change can conceal the symptom while the underlying join still multiplies records.","correct":true,"id":"F"},{"text":"Treat returning to preparation as a lifecycle failure","why":"Refinement can legitimately send the work back to an earlier stage.","correct":false,"id":"G"},{"text":"Accept the first revised total that looks familiar","why":"Independent reconciliation provides stronger support than a plausible appearance.","correct":false,"id":"H"}],"answer":"A display-level change can conceal the symptom while the underlying join still multiplies records. Successful execution does not establish the intended join cardinality or meaning. Independent reconciliation provides stronger support than a plausible appearance. Refinement can legitimately send the work back to an earlier stage.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q01"},{"ksb":"K3","objective":"Reviewing impact","prompt":"After handover, users report that a recurring dashboard's refresh misses their decision meeting. Which lifecycle lessons are appropriate?","options":[{"text":"Investigate refresh dependencies and ownership","why":"A refresh problem can arise from operational dependencies rather than the analytical method.","correct":true,"id":"A"},{"text":"Agree and test a revised refresh or delivery arrangement","why":"An implementable improvement must respect the actual source and processing constraints.","correct":true,"id":"B"},{"text":"Record the lesson for future planning","why":"Feedback about use can inform implementation and improve the planning of future work.","correct":true,"id":"C"},{"text":"Assume the delay proves the original statistical method was wrong","why":"A refresh problem can arise from operational dependencies rather than the analytical method.","correct":false,"id":"D"},{"text":"Judge success only by whether the first report was delivered","why":"Timing of recurring use is part of whether the output serves its intended purpose.","correct":false,"id":"E"},{"text":"Promise an earlier refresh without checking source availability","why":"An implementable improvement must respect the actual source and processing constraints.","correct":false,"id":"F"},{"text":"Review whether implementation met the agreed usage need","why":"Timing of recurring use is part of whether the output serves its intended purpose.","correct":true,"id":"G"},{"text":"Treat post-handover feedback as outside the analytics lifecycle","why":"Feedback about use can inform implementation and improve the planning of future work.","correct":false,"id":"H"}],"answer":"Timing of recurring use is part of whether the output serves its intended purpose. A refresh problem can arise from operational dependencies rather than the analytical method. An implementable improvement must respect the actual source and processing constraints. Feedback about use can inform implementation and improve the planning of future work.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q02"},{"ksb":"K3","objective":"Communication and implementation","prompt":"A validated analysis is ready for a service manager who must decide on staffing. Which handover activities complete the lifecycle appropriately?","options":[{"text":"Omit caveats because the analysis has already been validated","why":"Validation does not erase limitations, and delivery is not evidence of implementation or adoption.","correct":false,"id":"A"},{"text":"Treat file delivery as proof that the recommendation was adopted","why":"Validation does not erase limitations, and delivery is not evidence of implementation or adoption.","correct":false,"id":"B"},{"text":"Assume the analyst will remain the permanent owner without discussion","why":"Implementation needs explicit responsibility rather than an unspoken dependency.","correct":false,"id":"C"},{"text":"Explain how the recommendation relates to operational constraints","why":"Operational choices require context and judgement beyond a visual result.","correct":true,"id":"D"},{"text":"Send a notebook link without explaining the implication","why":"The audience needs an understandable account of what the result means for its decision.","correct":false,"id":"E"},{"text":"Present the recommendation as guaranteed by the chart","why":"Operational choices require context and judgement beyond a visual result.","correct":false,"id":"F"},{"text":"Agree ownership and refresh arrangements for recurring use","why":"Implementation needs explicit responsibility rather than an unspoken dependency.","correct":true,"id":"G"},{"text":"Explain the decision-relevant finding and its limitations","why":"The audience needs an understandable account of what the result means for its decision.","correct":true,"id":"H"}],"answer":"The audience needs an understandable account of what the result means for its decision. Implementation needs explicit responsibility rather than an unspoken dependency. Operational choices require context and judgement beyond a visual result. Validation does not erase limitations, and delivery is not evidence of implementation or adoption.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q03"},{"ksb":"K3","objective":"Choosing analysis","prompt":"The agreed question is whether completion times differ between two services. Data is prepared, but a colleague wants a forecast because it looks advanced. Which decisions belong in analysis?","options":[{"text":"Inspect distributions and relevant group sizes","why":"Distribution, design and sample information help determine a suitable comparison.","correct":true,"id":"A"},{"text":"Claim every analysis project requires predictive modelling","why":"Complexity and prediction are not universal requirements for answering a particular analytical question.","correct":false,"id":"B"},{"text":"Select a statistical method solely from its popularity","why":"Distribution, design and sample information help determine a suitable comparison.","correct":false,"id":"C"},{"text":"Choose summaries and comparisons that address the agreed difference","why":"Analytical methods should address the agreed question unless scope is explicitly changed.","correct":true,"id":"D"},{"text":"Replace the question with forecasting without stakeholder agreement","why":"Analytical methods should address the agreed question unless scope is explicitly changed.","correct":false,"id":"E"},{"text":"Explain assumptions and limits of the selected method","why":"A result needs a reasoned method choice and an account of its limitations.","correct":true,"id":"F"},{"text":"Treat a software-generated output as sufficient justification","why":"A result needs a reasoned method choice and an account of its limitations.","correct":false,"id":"G"},{"text":"Use the most complex method as the success criterion","why":"Complexity and prediction are not universal requirements for answering a particular analytical question.","correct":false,"id":"H"}],"answer":"Analytical methods should address the agreed question unless scope is explicitly changed. Distribution, design and sample information help determine a suitable comparison. A result needs a reasoned method choice and an account of its limitations. Complexity and prediction are not universal requirements for answering a particular analytical question.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q04"},{"ksb":"K3","objective":"Iteration after feedback","prompt":"In a prototype review, users reveal that the measure should use working days rather than calendar days. Which lifecycle response is justified?","options":[{"text":"Relabel the current numbers as working days","why":"Changing a label without recalculation misrepresents the measure.","correct":false,"id":"A"},{"text":"Validate the revised results and explain the effect of the change","why":"Changed calculations require relevant checks of the changed output.","correct":true,"id":"B"},{"text":"Confirm the revised definition and scope with stakeholders","why":"Changing a label without recalculation misrepresents the measure.","correct":true,"id":"C"},{"text":"Change only the final chart caption","why":"The definition affects the transformation and calculations as well as communication.","correct":false,"id":"D"},{"text":"Document the feedback and resulting iteration","why":"A truthful lifecycle account explains why revisiting earlier stages improved the work.","correct":true,"id":"E"},{"text":"Update preparation and calculations to implement the agreed definition","why":"The definition affects the transformation and calculations as well as communication.","correct":true,"id":"F"},{"text":"Hide the iteration to present a perfectly linear process","why":"A truthful lifecycle account explains why revisiting earlier stages improved the work.","correct":false,"id":"G"},{"text":"Keep the original validation record as proof that new values are correct","why":"Changed calculations require relevant checks of the changed output.","correct":false,"id":"H"}],"answer":"Changing a label without recalculation misrepresents the measure. The definition affects the transformation and calculations as well as communication. Changed calculations require relevant checks of the changed output. A truthful lifecycle account explains why revisiting earlier stages improved the work.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q05"},{"ksb":"K3","objective":"Lifecycle evidence","prompt":"A project account contains a brief, cleaning log, analytical output, validation notes and stakeholder handover. Which links explain the lifecycle coherently?","options":[{"text":"Connect the brief's question to the selected analytical method","why":"A continuous account shows how the method answered the planned question.","correct":true,"id":"A"},{"text":"Treat the cleaning log as evidence that no later checks were needed","why":"Preparation and validation have related but distinct roles.","correct":false,"id":"B"},{"text":"Describe each document without explaining their relationships","why":"A continuous account shows how the method answered the planned question.","correct":false,"id":"C"},{"text":"Connect preparation decisions to the validated output","why":"Preparation and validation have related but distinct roles.","correct":true,"id":"D"},{"text":"Attribute every team activity to yourself to fill the lifecycle","why":"The lifecycle narrative needs truthful attribution of individual and collaborative work.","correct":false,"id":"E"},{"text":"Identify your own actions at each relevant stage","why":"The lifecycle narrative needs truthful attribution of individual and collaborative work.","correct":true,"id":"F"},{"text":"Claim communication happened only because a file exists","why":"A handover account should explain the audience, message and practical use, not infer communication from a file.","correct":false,"id":"G"},{"text":"Explain how the handover used findings and limitations","why":"A handover account should explain the audience, message and practical use, not infer communication from a file.","correct":true,"id":"H"}],"answer":"A continuous account shows how the method answered the planned question. Preparation and validation have related but distinct roles. A handover account should explain the audience, message and practical use, not infer communication from a file. The lifecycle narrative needs truthful attribution of individual and collaborative work.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q06"},{"ksb":"K3","objective":"Comparison boundaries","prompt":"A project compares two cleaning approaches. One removes incomplete rows; another uses justified imputation. Which refining account is strongest?","options":[{"text":"Treat matching overall averages as proof the two cleaning approaches are equivalent","why":"The comparison needs to consider affected records, subgroup results and assumptions; matching one aggregate does not establish equivalent analytical consequences.","correct":false,"id":"A"},{"text":"Compare results and assumptions under both treatments","why":"Refinement should evaluate justified treatments rather than optimise a desired conclusion.","correct":true,"id":"B"},{"text":"Compare how each treatment changes the analysed population","why":"Population differences can affect interpretation; small file size is not the analytical objective.","correct":true,"id":"C"},{"text":"Explain why the retained approach suits the decision","why":"Imputed values depend on assumptions and should not be described as observed truth.","correct":true,"id":"D"},{"text":"Claim the rejected approach was never considered","why":"The comparison needs to consider affected records, subgroup results and assumptions; matching one aggregate does not establish equivalent analytical consequences.","correct":false,"id":"E"},{"text":"Select whichever approach produces the smallest dataset","why":"Population differences can affect interpretation; small file size is not the analytical objective.","correct":false,"id":"F"},{"text":"Choose the approach that yields the preferred headline","why":"Refinement should evaluate justified treatments rather than optimise a desired conclusion.","correct":false,"id":"G"},{"text":"Present imputation as an automatic restoration of known facts","why":"Imputed values depend on assumptions and should not be described as observed truth.","correct":false,"id":"H"}],"answer":"Population differences can affect interpretation; small file size is not the analytical objective. Refinement should evaluate justified treatments rather than optimise a desired conclusion. Imputed values depend on assumptions and should not be described as observed truth. The comparison needs to consider affected records, subgroup results and assumptions; matching one aggregate does not establish equivalent analytical consequences.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q07"},{"ksb":"K3","objective":"Planning a measure","prompt":"A manager asks whether a new triage process reduced waiting times. No population, comparison period or success criterion has been agreed. Which activities belong in planning?","options":[{"text":"Assume the largest available extract defines the intended population","why":"Prior scope and available volume do not establish the current question, population and decision boundaries.","correct":false,"id":"A"},{"text":"Agree which cases and waiting-time definition to use","why":"Defining the population and measure prevents an available column from silently determining the question.","correct":true,"id":"B"},{"text":"Choose the most favourable comparison after inspecting all results","why":"A planned comparison reduces the risk of selecting a convenient result after analysis.","correct":false,"id":"C"},{"text":"Identify stakeholders, access needs and delivery risks","why":"Access and stakeholder dependencies affect whether the proposed project is feasible.","correct":true,"id":"D"},{"text":"Reuse last year's scope without confirming the new question","why":"Prior scope and available volume do not establish the current question, population and decision boundaries.","correct":false,"id":"E"},{"text":"Agree a feasible comparison and decision criterion","why":"A planned comparison reduces the risk of selecting a convenient result after analysis.","correct":true,"id":"F"},{"text":"Leave access dependencies until the final dashboard review","why":"Access and stakeholder dependencies affect whether the proposed project is feasible.","correct":false,"id":"G"},{"text":"Start averaging whichever duration column is easiest to export","why":"Defining the population and measure prevents an available column from silently determining the question.","correct":false,"id":"H"}],"answer":"Defining the population and measure prevents an available column from silently determining the question. A planned comparison reduces the risk of selecting a convenient result after analysis. Access and stakeholder dependencies affect whether the proposed project is feasible. Prior scope and available volume do not establish the current question, population and decision boundaries.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q08"},{"ksb":"K3","objective":"Scope change during analysis","prompt":"While you analyse quarterly delays, the sponsor requests a new customer segmentation. It needs different data and additional time. Which actions preserve a coherent lifecycle?","options":[{"text":"Add the segmentation silently to the current scope","why":"A materially different requirement needs an explicit assessment of feasibility and impact.","correct":false,"id":"A"},{"text":"Plan suitable preparation and validation for the new task","why":"A different analytical task can need different data and checks.","correct":true,"id":"B"},{"text":"Classify the request as a presentation-only change","why":"Different data and analytical aims cannot be satisfied merely by relabelling the output.","correct":false,"id":"C"},{"text":"Promise both outputs before assessing data access","why":"Delivery commitments should reflect the changed workload and access needs.","correct":false,"id":"D"},{"text":"Agree priorities or revised delivery boundaries","why":"Delivery commitments should reflect the changed workload and access needs.","correct":true,"id":"E"},{"text":"Revisit planning to assess the new requirement and dependencies","why":"A materially different requirement needs an explicit assessment of feasibility and impact.","correct":true,"id":"F"},{"text":"Reuse the delay-analysis checks as complete segmentation validation","why":"A different analytical task can need different data and checks.","correct":false,"id":"G"},{"text":"Treat an added chart as proof that segmentation was implemented","why":"Different data and analytical aims cannot be satisfied merely by relabelling the output.","correct":false,"id":"H"}],"answer":"A materially different requirement needs an explicit assessment of feasibility and impact. Delivery commitments should reflect the changed workload and access needs. A different analytical task can need different data and checks. Different data and analytical aims cannot be satisfied merely by relabelling the output.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q09"},{"ksb":"K3","objective":"Preparing dates","prompt":"During preparation, start dates are text in two formats and some closure dates precede starts. Which actions fit this lifecycle stage?","options":[{"text":"Profile and investigate impossible intervals","why":"Changing signs can conceal a source or interpretation error rather than resolve it.","correct":true,"id":"A"},{"text":"Assume every ambiguous date uses your computer's locale","why":"Source conventions must determine interpretation; a local default can reverse day and month.","correct":false,"id":"B"},{"text":"Overwrite the original extract before recording corrections","why":"Retaining provenance supports checking the preparation and reproducing its results.","correct":false,"id":"C"},{"text":"Proceed as though successful parsing proves every date accurate","why":"A parsed value can still be wrong; unresolved issues need an impact assessment.","correct":false,"id":"D"},{"text":"Parse dates using confirmed source conventions","why":"Source conventions must determine interpretation; a local default can reverse day and month.","correct":true,"id":"E"},{"text":"Convert negative durations to positive values automatically","why":"Changing signs can conceal a source or interpretation error rather than resolve it.","correct":false,"id":"F"},{"text":"Preserve raw values and document transformations","why":"Retaining provenance supports checking the preparation and reproducing its results.","correct":true,"id":"G"},{"text":"Assess the impact of unresolved dates on the planned analysis","why":"A parsed value can still be wrong; unresolved issues need an impact assessment.","correct":true,"id":"H"}],"answer":"Source conventions must determine interpretation; a local default can reverse day and month. Changing signs can conceal a source or interpretation error rather than resolve it. Retaining provenance supports checking the preparation and reproducing its results. A parsed value can still be wrong; unresolved issues need an impact assessment.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."},"id":"T13-E2-Q10"}]},{"id":"T14","title":"K4 · Data Classification Types","description":"Data origin, reuse rights, purpose and separate sensitivity assessment.","questions":[{"ksb":"K4","objective":"Reasoned non-use","prompt":"Your project uses a sufficiently detailed administrative extract. Available survey data covers a different population. Which explanation of non-use is defensible?","options":[{"text":"State that one suitable source eliminates all analytical limitations","why":"Source selection can be justified while still acknowledging coverage or measurement limits.","correct":false,"id":"A"},{"text":"Note any remaining limitations of the chosen source","why":"Source selection can be justified while still acknowledging coverage or measurement limits.","correct":true,"id":"B"},{"text":"Claim the unused survey was combined to demonstrate breadth","why":"The account should describe actual sources and their contribution truthfully.","correct":false,"id":"C"},{"text":"Classify each worksheet as a different data category","why":"File divisions and references do not establish distinct collection types or actual integration.","correct":false,"id":"D"},{"text":"Explain the mismatch with the project's population","why":"This dataset may be unsuitable without implying that an entire category is unsuitable.","correct":true,"id":"E"},{"text":"Say research data is never useful in operational analysis","why":"This dataset may be unsuitable without implying that an entire category is unsuitable.","correct":false,"id":"F"},{"text":"Count an external hyperlink as evidence of source integration","why":"File divisions and references do not establish distinct collection types or actual integration.","correct":false,"id":"G"},{"text":"Explain how the administrative data serves the agreed question","why":"The account should describe actual sources and their contribution truthfully.","correct":true,"id":"H"}],"answer":"This dataset may be unsuitable without implying that an entire category is unsuitable. The account should describe actual sources and their contribution truthfully. Source selection can be justified while still acknowledging coverage or measurement limits. File divisions and references do not establish distinct collection types or actual integration.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q01"},{"ksb":"K4","objective":"Security classification","prompt":"An organisation labels a research extract 'restricted'. A colleague proposes replacing that label with 'research'. Which distinctions matter?","options":[{"text":"The restricted handling controls still apply","why":"Using records for analysis does not itself authorise relaxed handling.","correct":true,"id":"A"},{"text":"Invent a universal mapping from research to medium risk","why":"Sensitivity depends on the data and context within the actual organisational scheme.","correct":false,"id":"B"},{"text":"An analytical use cancels the existing sensitivity label","why":"Using records for analysis does not itself authorise relaxed handling.","correct":false,"id":"C"},{"text":"Apply the organisation's security scheme separately","why":"Sensitivity depends on the data and context within the actual organisational scheme.","correct":true,"id":"D"},{"text":"Treat every administrative dataset as highly sensitive without assessment","why":"Category labels alone do not determine the risk of the actual content and its proposed combinations.","correct":false,"id":"E"},{"text":"Research is the equivalent of a low-risk security label","why":"Collection purpose and security handling describe different aspects of the dataset.","correct":false,"id":"F"},{"text":"Treat every open dataset as harmless when linked","why":"Category labels alone do not determine the risk of the actual content and its proposed combinations.","correct":false,"id":"G"},{"text":"Research describes the data's collection purpose","why":"Collection purpose and security handling describe different aspects of the dataset.","correct":true,"id":"H"}],"answer":"Collection purpose and security handling describe different aspects of the dataset. Using records for analysis does not itself authorise relaxed handling. Sensitivity depends on the data and context within the actual organisational scheme. Category labels alone do not determine the risk of the actual content and its proposed combinations.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q02"},{"ksb":"K4","objective":"Research restrictions","prompt":"A university dataset was collected for a study under access conditions. Only approved researchers may use individual records. Which conclusions follow?","options":[{"text":"Academic authorship permits unrelated secondary use","why":"Authorship by a university does not remove the applicable access and reuse conditions.","correct":false,"id":"A"},{"text":"Proposed reuse must respect the study's conditions","why":"Authorship by a university does not remove the applicable access and reuse conditions.","correct":true,"id":"B"},{"text":"Treat the study sample as representative of every service user","why":"Representativeness depends on the actual design and coverage, not the research label alone.","correct":false,"id":"C"},{"text":"It can be research data despite restricted access","why":"Research classification concerns its purpose, not a requirement that it be open.","correct":true,"id":"D"},{"text":"Restricted access means it cannot be research data","why":"Research classification concerns its purpose, not a requirement that it be open.","correct":false,"id":"E"},{"text":"Infer participant consent for every future analysis from the journal article","why":"Published findings do not establish open record access or unlimited participant agreement.","correct":false,"id":"F"},{"text":"Classify the records as open because findings were published","why":"Published findings do not establish open record access or unlimited participant agreement.","correct":false,"id":"G"},{"text":"Assess sample and collection design before drawing conclusions","why":"Representativeness depends on the actual design and coverage, not the research label alone.","correct":true,"id":"H"}],"answer":"Research classification concerns its purpose, not a requirement that it be open. Authorship by a university does not remove the applicable access and reuse conditions. Representativeness depends on the actual design and coverage, not the research label alone. Published findings do not establish open record access or unlimited participant agreement.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q03"},{"ksb":"K4","objective":"Survey versus service register","prompt":"One dataset comes from a deliberately sampled satisfaction survey; another logs every booking in a service system. Which distinctions should guide their use?","options":[{"text":"Check comparable populations before combining findings","why":"A shared subject does not make collection designs and represented populations equivalent.","correct":true,"id":"A"},{"text":"Treat the two sources as interchangeable because both concern the service","why":"A shared subject does not make collection designs and represented populations equivalent.","correct":false,"id":"B"},{"text":"Treat every survey percentage as a full-population rate","why":"Survey inference depends on coverage, response and sampling assumptions.","correct":false,"id":"C"},{"text":"Assume the register includes people who never attempted to book","why":"Operational records cover recorded interactions, not necessarily all unmet need.","correct":false,"id":"D"},{"text":"Examine sampling and non-response in the survey","why":"Survey inference depends on coverage, response and sampling assumptions.","correct":true,"id":"E"},{"text":"Infer purpose from whether the file is CSV or Excel","why":"File format does not determine whether collection was operational or research-based.","correct":false,"id":"F"},{"text":"Examine which events the booking system records","why":"Operational records cover recorded interactions, not necessarily all unmet need.","correct":true,"id":"G"},{"text":"Explain the collection purpose of each source","why":"File format does not determine whether collection was operational or research-based.","correct":true,"id":"H"}],"answer":"Survey inference depends on coverage, response and sampling assumptions. Operational records cover recorded interactions, not necessarily all unmet need. File format does not determine whether collection was operational or research-based. A shared subject does not make collection designs and represented populations equivalent.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q04"},{"ksb":"K4","objective":"Public versus open","prompt":"A council publishes a report online, but its terms prohibit redistribution of the underlying table. Which conclusions are justified?","options":[{"text":"Classify it as research solely because it contains statistics","why":"Hosting organisation and numerical content do not establish how or why the records were produced.","correct":false,"id":"A"},{"text":"Remove the publisher's name to make reuse permissible","why":"Removing attribution does not resolve a restriction and may introduce another problem.","correct":false,"id":"B"},{"text":"Classify the table as administrative solely because a council hosts it","why":"Hosting organisation and numerical content do not establish how or why the records were produced.","correct":false,"id":"C"},{"text":"Seek permission or a suitable licensed alternative","why":"Removing attribution does not resolve a restriction and may introduce another problem.","correct":true,"id":"D"},{"text":"Check the licence before incorporating the table","why":"The licence and its conditions determine permitted reuse, rather than the download mechanism.","correct":true,"id":"E"},{"text":"Online access establishes unrestricted reuse rights","why":"Public access describes availability; it does not by itself grant an open reuse licence.","correct":false,"id":"F"},{"text":"Treat a download button as permission to redistribute","why":"The licence and its conditions determine permitted reuse, rather than the download mechanism.","correct":false,"id":"G"},{"text":"The report is publicly accessible","why":"Public access describes availability; it does not by itself grant an open reuse licence.","correct":true,"id":"H"}],"answer":"Public access describes availability; it does not by itself grant an open reuse licence. The licence and its conditions determine permitted reuse, rather than the download mechanism. Removing attribution does not resolve a restriction and may introduce another problem. Hosting organisation and numerical content do not establish how or why the records were produced.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q05"},{"ksb":"K4","objective":"Administrative origin","prompt":"Appointment records were created to schedule and deliver a service. They are later used in a performance study. Which descriptions fit?","options":[{"text":"Later statistical analysis proves they were originally research data","why":"Subsequent analysis does not erase the service purpose that generated the records.","correct":false,"id":"A"},{"text":"Their operational origin supports an administrative classification","why":"Subsequent analysis does not erase the service purpose that generated the records.","correct":true,"id":"B"},{"text":"Explain the original collection purpose in the analysis","why":"A service register should not be represented as a survey with a sampling design it did not have.","correct":true,"id":"C"},{"text":"Access may remain restricted because records identify people","why":"Administrative origin does not establish a public access right or low sensitivity.","correct":true,"id":"D"},{"text":"Describe the records as a designed survey sample","why":"A service register should not be represented as a survey with a sampling design it did not have.","correct":false,"id":"E"},{"text":"Their suitability for the study still needs checking","why":"Records collected for service delivery may omit variables or populations needed for the later question.","correct":true,"id":"F"},{"text":"Administrative data must be publicly accessible","why":"Administrative origin does not establish a public access right or low sensitivity.","correct":false,"id":"G"},{"text":"Operational collection guarantees research-quality measurement","why":"Records collected for service delivery may omit variables or populations needed for the later question.","correct":false,"id":"H"}],"answer":"Subsequent analysis does not erase the service purpose that generated the records. Records collected for service delivery may omit variables or populations needed for the later question. Administrative origin does not establish a public access right or low sensitivity. A service register should not be represented as a survey with a sampling design it did not have.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q06"},{"ksb":"K4","objective":"Overlapping categories","prompt":"A service publishes suitably protected aggregate statistics from its operational register under an open licence. Which statements describe this release?","options":[{"text":"Administrative origin prevents an open aggregate release","why":"Origin and licensed reuse can coexist; these categories are not exclusive boxes.","correct":false,"id":"A"},{"text":"The source records have an administrative origin","why":"Publication changes availability and representation, not the original operational collection purpose.","correct":true,"id":"B"},{"text":"Publishing aggregates changes how the original records were collected","why":"Publication changes availability and representation, not the original operational collection purpose.","correct":false,"id":"C"},{"text":"Explain which version and licence the project used","why":"The analytical account should identify the actual released dataset used.","correct":true,"id":"D"},{"text":"The identifiable source register can remain restricted","why":"A release licence for aggregates does not automatically cover the underlying identifiable records.","correct":true,"id":"E"},{"text":"The released aggregates may be open data under that licence","why":"Origin and licensed reuse can coexist; these categories are not exclusive boxes.","correct":true,"id":"F"},{"text":"Cite the original register as though you accessed individual records","why":"The analytical account should identify the actual released dataset used.","correct":false,"id":"G"},{"text":"Open aggregates imply an open right to every source record","why":"A release licence for aggregates does not automatically cover the underlying identifiable records.","correct":false,"id":"H"}],"answer":"Publication changes availability and representation, not the original operational collection purpose. Origin and licensed reuse can coexist; these categories are not exclusive boxes. A release licence for aggregates does not automatically cover the underlying identifiable records. The analytical account should identify the actual released dataset used.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q07"},{"ksb":"K4","objective":"Population mismatch","prompt":"An openly licensed regional table is proposed as context for a local service dashboard. Its age bands and geography differ from the dashboard population. Which checks are necessary?","options":[{"text":"Assume open licensing makes populations comparable","why":"Licensing permits specified reuse; it does not establish analytical comparability.","correct":false,"id":"A"},{"text":"Omit provenance because the table is open","why":"Open data can still require attribution and benefits from traceable release information.","correct":false,"id":"B"},{"text":"Retain the release date and source attribution","why":"Open data can still require attribution and benefits from traceable release information.","correct":true,"id":"C"},{"text":"Divide regional totals by local counts without assessing denominators","why":"A comparison needs compatible definitions and a defensible denominator.","correct":false,"id":"D"},{"text":"Explain limitations or reject unsuitable comparisons","why":"A comparison needs compatible definitions and a defensible denominator.","correct":true,"id":"E"},{"text":"Check whether age bands can be combined defensibly","why":"Relabelling does not make differently defined groups equivalent.","correct":true,"id":"F"},{"text":"Compare the population definitions and geography","why":"Licensing permits specified reuse; it does not establish analytical comparability.","correct":true,"id":"G"},{"text":"Rename the regional bands to match the local labels","why":"Relabelling does not make differently defined groups equivalent.","correct":false,"id":"H"}],"answer":"Licensing permits specified reuse; it does not establish analytical comparability. Relabelling does not make differently defined groups equivalent. A comparison needs compatible definitions and a defensible denominator. Open data can still require attribution and benefits from traceable release information.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q08"},{"ksb":"K4","objective":"Licence obligations","prompt":"A relevant open dataset permits reuse with attribution and a change notice. You clean and republish a subset. Which actions follow?","options":[{"text":"Identify relevant modifications to the released data","why":"A change notice helps distinguish your transformation from the original release.","correct":true,"id":"A"},{"text":"Drop attribution because only a subset is used","why":"Reusing a subset does not automatically remove the licence conditions.","correct":false,"id":"B"},{"text":"Verify that the intended redistribution is covered","why":"Terms should be checked for the specific dataset and intended use.","correct":true,"id":"C"},{"text":"Describe permitted reuse as evidence that the data is error-free","why":"A licence addresses permissions, not the accuracy or endorsement of analytical conclusions.","correct":false,"id":"D"},{"text":"Assume every dataset on the same site has identical terms","why":"Terms should be checked for the specific dataset and intended use.","correct":false,"id":"E"},{"text":"Attribute the dataset as its licence requires","why":"Reusing a subset does not automatically remove the licence conditions.","correct":true,"id":"F"},{"text":"Claim the open licence certifies your derived estimates","why":"A licence addresses permissions, not the accuracy or endorsement of analytical conclusions.","correct":false,"id":"G"},{"text":"Present the cleaned subset as the publisher's unmodified original","why":"A change notice helps distinguish your transformation from the original release.","correct":false,"id":"H"}],"answer":"Reusing a subset does not automatically remove the licence conditions. A change notice helps distinguish your transformation from the original release. Terms should be checked for the specific dataset and intended use. A licence addresses permissions, not the accuracy or endorsement of analytical conclusions.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q09"},{"ksb":"K4","objective":"Public personal information","prompt":"Named professional contact details are visible on an organisation's website. A project proposes collecting them into a new profiling dataset. Which considerations remain relevant?","options":[{"text":"Infer consent to profiling from publication of a contact page","why":"A public contact purpose does not by itself establish agreement to a separate profiling purpose.","correct":false,"id":"A"},{"text":"Classify the dataset as open solely because collection needs no login","why":"Neither login requirements nor the collector's job title establishes the relevant data category and permissions.","correct":false,"id":"B"},{"text":"Assess the intended purpose and applicable handling rules","why":"Availability does not establish that every new collection or use is justified.","correct":true,"id":"C"},{"text":"Treat public visibility as unrestricted permission for profiling","why":"Availability does not establish that every new collection or use is justified.","correct":false,"id":"D"},{"text":"Check reuse terms and expectations in context","why":"A public contact purpose does not by itself establish agreement to a separate profiling purpose.","correct":true,"id":"E"},{"text":"Treat website publication as automatic anonymisation","why":"Publicly visible information can remain information about identifiable individuals.","correct":false,"id":"F"},{"text":"Consider whether the collected details identify people","why":"Publicly visible information can remain information about identifiable individuals.","correct":true,"id":"G"},{"text":"Classify it as research solely because an analyst collects it","why":"Neither login requirements nor the collector's job title establishes the relevant data category and permissions.","correct":false,"id":"H"}],"answer":"Availability does not establish that every new collection or use is justified. Publicly visible information can remain information about identifiable individuals. A public contact purpose does not by itself establish agreement to a separate profiling purpose. Neither login requirements nor the collector's job title establishes the relevant data category and permissions.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T14-E2-Q10"}]},{"id":"T15","title":"K5 · Structured vs. Unstructured Data","description":"Schema, nested records, free text and preparation choices.","questions":[{"ksb":"K5","objective":"Thematic coding","prompt":"You code 40 comments into themes, allowing a comment to mention several themes. There are 62 theme assignments. Which interpretations are correct?","options":[{"text":"Treat all themes as mutually exclusive in the chart","why":"Multiple assignments do not establish distinct people or mutually exclusive categories.","correct":false,"id":"A"},{"text":"Report 62 distinct people from the assignment count","why":"Multiple assignments do not establish distinct people or mutually exclusive categories.","correct":false,"id":"B"},{"text":"The count can exceed the number of comments","why":"Multiple themes per comment can legitimately produce more assignments than comments.","correct":true,"id":"C"},{"text":"Label both denominators simply as respondents","why":"Different denominators answer different questions and should be named clearly.","correct":false,"id":"D"},{"text":"Apply the same coding rules across comments","why":"The stated coding allows multiple themes; forcing exclusive categories changes the method and can discard relevant meaning. Apply consistent coding rules to the content.","correct":true,"id":"E"},{"text":"Explain whether percentages use comments or assignments","why":"Different denominators answer different questions and should be named clearly.","correct":true,"id":"F"},{"text":"The count proves that 22 comments were duplicated in storage","why":"Multiple themes per comment can legitimately produce more assignments than comments.","correct":false,"id":"G"},{"text":"Force one theme per comment to make the theme counts sum to forty","why":"The stated coding allows multiple themes; forcing exclusive categories changes the method and can discard relevant meaning. Apply consistent coding rules to the content.","correct":false,"id":"H"}],"answer":"Multiple themes per comment can legitimately produce more assignments than comments. Different denominators answer different questions and should be named clearly. The stated coding allows multiple themes; forcing exclusive categories changes the method and can discard relevant meaning. Apply consistent coding rules to the content. Multiple assignments do not establish distinct people or mutually exclusive categories.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q01"},{"ksb":"K5","objective":"Nested JSON","prompt":"An API returns one customer object containing an array of orders. The analysis needs one row per order. Which transformations are justified?","options":[{"text":"Assume JSON has no structural organisation","why":"Keys and nested arrays provide organisation even when the representation is not one rectangular table.","correct":false,"id":"A"},{"text":"Check the resulting order count against array lengths","why":"The analytical grain changes from customers to orders, so row counts can legitimately increase.","correct":true,"id":"B"},{"text":"Expand orders while retaining their customer identifier","why":"Expansion should retain all relevant orders, not silently discard later array elements.","correct":true,"id":"C"},{"text":"Handle customers with no orders according to the question","why":"An empty array is not evidence of an actual order and needs explicit treatment.","correct":true,"id":"D"},{"text":"Keep only the first order in each customer object","why":"Expansion should retain all relevant orders, not silently discard later array elements.","correct":false,"id":"E"},{"text":"Describe JSON as structured hierarchically rather than a flat table","why":"Keys and nested arrays provide organisation even when the representation is not one rectangular table.","correct":true,"id":"F"},{"text":"Invent an order for each empty array to preserve counts","why":"An empty array is not evidence of an actual order and needs explicit treatment.","correct":false,"id":"G"},{"text":"Expect the expanded table to retain the customer row count","why":"The analytical grain changes from customers to orders, so row counts can legitimately increase.","correct":false,"id":"H"}],"answer":"Expansion should retain all relevant orders, not silently discard later array elements. The analytical grain changes from customers to orders, so row counts can legitimately increase. An empty array is not evidence of an actual order and needs explicit treatment. Keys and nested arrays provide organisation even when the representation is not one rectangular table.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q02"},{"ksb":"K5","objective":"Choosing preparation","prompt":"A project combines transaction totals with interview themes. Which decisions account for their different structures?","options":[{"text":"Convert all amounts into prose before any comparison","why":"Changing representation does not resolve the difference between quantitative amounts and qualitative categories.","correct":false,"id":"A"},{"text":"Use a documented interpretation process for interview themes","why":"Narrative interpretation requires methods appropriate to its meaning and structure.","correct":true,"id":"B"},{"text":"Assign arbitrary numbers to themes and correlate them as magnitudes","why":"Changing representation does not resolve the difference between quantitative amounts and qualitative categories.","correct":false,"id":"C"},{"text":"Apply numeric missing-value imputation directly to whole interview narratives","why":"Narrative interpretation requires methods appropriate to its meaning and structure.","correct":false,"id":"D"},{"text":"Join each interview to the nearest amount merely to fill every row","why":"A relationship needs a meaningful key or justified analytical design, not an arbitrary proximity match.","correct":false,"id":"E"},{"text":"Summarise transactions at whichever grain the export happens to use","why":"The analytical question determines the appropriate unit and aggregation.","correct":false,"id":"F"},{"text":"Explain how themes and totals relate without forcing a one-to-one match","why":"A relationship needs a meaningful key or justified analytical design, not an arbitrary proximity match.","correct":true,"id":"G"},{"text":"Aggregate transactions at the required business grain","why":"The analytical question determines the appropriate unit and aggregation.","correct":true,"id":"H"}],"answer":"The analytical question determines the appropriate unit and aggregation. Narrative interpretation requires methods appropriate to its meaning and structure. A relationship needs a meaningful key or justified analytical design, not an arbitrary proximity match. Changing representation does not resolve the difference between quantitative amounts and qualitative categories.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q03"},{"ksb":"K5","objective":"Audio extraction","prompt":"Recorded interviews will be analysed for recurring service concerns. Which preparation choices address unstructured audio?","options":[{"text":"Treat audio file size as a measure of dissatisfaction","why":"File size does not establish the meaning or sentiment of the interview content.","correct":false,"id":"A"},{"text":"Explain coding decisions and uncertainty in interpretation","why":"A concern can be expressed without the chosen word, and a word can occur without that concern.","correct":true,"id":"B"},{"text":"Create or obtain an appropriate transcript before coding text","why":"File size does not establish the meaning or sentiment of the interview content.","correct":true,"id":"C"},{"text":"Treat a keyword count as an exact count of expressed concerns","why":"A concern can be expressed without the chosen word, and a word can occur without that concern.","correct":false,"id":"D"},{"text":"Retain authorised provenance between transcript and recording","why":"Controlled provenance supports quality review while still requiring appropriate access protection.","correct":true,"id":"E"},{"text":"Check transcription errors that could change meaning","why":"Domain terms and recording conditions can introduce errors requiring review.","correct":true,"id":"F"},{"text":"Remove all linkage before checking the transcription","why":"Controlled provenance supports quality review while still requiring appropriate access protection.","correct":false,"id":"G"},{"text":"Assume automatic transcription captures every term accurately","why":"Domain terms and recording conditions can introduce errors requiring review.","correct":false,"id":"H"}],"answer":"File size does not establish the meaning or sentiment of the interview content. Domain terms and recording conditions can introduce errors requiring review. Controlled provenance supports quality review while still requiring appropriate access protection. A concern can be expressed without the chosen word, and a word can occur without that concern.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q04"},{"ksb":"K5","objective":"Semi-structured logs","prompt":"Server logs contain a timestamp, event code and a variable message. Some messages include nested details. Which preparation approach fits?","options":[{"text":"Split every line on spaces and assume identical field positions","why":"Variable messages can break simplistic positional splitting.","correct":false,"id":"A"},{"text":"Reconcile parsed and rejected record counts","why":"A table's existence does not show how much source information was retained or lost.","correct":true,"id":"B"},{"text":"Discard failed parses without counting them","why":"Unexamined failures can bias the analysed events and hide preparation problems.","correct":false,"id":"C"},{"text":"Preserve relevant raw messages for authorised investigation","why":"Unexamined failures can bias the analysed events and hide preparation problems.","correct":true,"id":"D"},{"text":"Measure success only by whether a table was produced","why":"A table's existence does not show how much source information was retained or lost.","correct":false,"id":"E"},{"text":"Inspect message variants before deciding what to extract","why":"One example may omit important variants and optional fields.","correct":true,"id":"F"},{"text":"Derive the schema from one convenient log entry","why":"One example may omit important variants and optional fields.","correct":false,"id":"G"},{"text":"Extract stable fields using the documented log structure","why":"Variable messages can break simplistic positional splitting.","correct":true,"id":"H"}],"answer":"Variable messages can break simplistic positional splitting. One example may omit important variants and optional fields. Unexamined failures can bias the analysed events and hide preparation problems. A table's existence does not show how much source information was retained or lost.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q05"},{"ksb":"K5","objective":"OCR documents","prompt":"A scanned invoice becomes a table through optical character recognition. Some decimal points are misread. Which conclusions follow?","options":[{"text":"Correct every large amount by dividing by ten","why":"Neither a universal adjustment nor assumed cancellation is justified by the stated extraction problem.","correct":false,"id":"A"},{"text":"Validate only that the extracted cells contain numbers","why":"Numeric typing alone will not detect a misplaced decimal point.","correct":false,"id":"B"},{"text":"Preserve enough source traceability to investigate errors","why":"Relevant authorised source references support checking extraction errors.","correct":true,"id":"C"},{"text":"Delete images before reviewing suspicious extracted totals","why":"Relevant authorised source references support checking extraction errors.","correct":false,"id":"D"},{"text":"Treat all OCR differences as random noise that cancels in totals","why":"Neither a universal adjustment nor assumed cancellation is justified by the stated extraction problem.","correct":false,"id":"E"},{"text":"Reconcile important amounts against the source image","why":"Numeric typing alone will not detect a misplaced decimal point.","correct":true,"id":"F"},{"text":"A table output proves the source was already a reliable structured dataset","why":"Structural conversion does not guarantee extraction accuracy or establish the original format's quality.","correct":false,"id":"G"},{"text":"Extraction has produced structured fields that need validation","why":"Structural conversion does not guarantee extraction accuracy or establish the original format's quality.","correct":true,"id":"H"}],"answer":"Structural conversion does not guarantee extraction accuracy or establish the original format's quality. Numeric typing alone will not detect a misplaced decimal point. Relevant authorised source references support checking extraction errors. Neither a universal adjustment nor assumed cancellation is justified by the stated extraction problem.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q06"},{"ksb":"K5","objective":"Text inside tables","prompt":"A CSV has request IDs, dates and a free-text complaint column. Which description best supports preparation?","options":[{"text":"Treat every complaint as a numeric measure after assigning a row number","why":"Typed fields remain useful, and row numbering does not convert a narrative into a quantitative measurement.","correct":false,"id":"A"},{"text":"Treat the entire file as unstructured and discard typed fields","why":"Typed fields remain useful, and row numbering does not convert a narrative into a quantitative measurement.","correct":false,"id":"B"},{"text":"Alphabetical sorting is sufficient thematic analysis","why":"Sorting words or cells does not identify and consistently apply meaningful themes.","correct":false,"id":"C"},{"text":"The rows and named fields provide a structured container","why":"A tabular container can contain narrative content whose meaning needs interpretation.","correct":true,"id":"D"},{"text":"Split comments from IDs without retaining a linkage","why":"A controlled linkage helps maintain the analytical unit and trace interpretations to records.","correct":false,"id":"E"},{"text":"Every field's meaning is structured because the file is CSV","why":"A tabular container can contain narrative content whose meaning needs interpretation.","correct":false,"id":"F"},{"text":"Complaint narratives may need coding before thematic counts","why":"Sorting words or cells does not identify and consistently apply meaningful themes.","correct":true,"id":"G"},{"text":"Preserve the relationship between each comment and request","why":"A controlled linkage helps maintain the analytical unit and trace interpretations to records.","correct":true,"id":"H"}],"answer":"A tabular container can contain narrative content whose meaning needs interpretation. Sorting words or cells does not identify and consistently apply meaningful themes. A controlled linkage helps maintain the analytical unit and trace interpretations to records. Typed fields remain useful, and row numbering does not convert a narrative into a quantitative measurement.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q07"},{"ksb":"K5","objective":"Images as analytical input","prompt":"A project counts damaged road signs from photographs. Which explanation connects unstructured input to a structured result?","options":[{"text":"Infer classification accuracy from the number of processed images","why":"Processing volume does not measure the quality of the classifications.","correct":false,"id":"A"},{"text":"Retain appropriate uncertainty and sampling limitations","why":"Conclusions depend on the sampled images and the accuracy of the extraction process.","correct":true,"id":"B"},{"text":"Record image-derived categories as a new structured field","why":"The label is a derived interpretation, not an original verified tabular field.","correct":true,"id":"C"},{"text":"Check reviewer or model errors on suitable examples","why":"Processing volume does not measure the quality of the classifications.","correct":true,"id":"D"},{"text":"Claim the category existed as a verified field in the original photograph","why":"The label is a derived interpretation, not an original verified tabular field.","correct":false,"id":"E"},{"text":"Treat the photographed locations as every road in the region","why":"Conclusions depend on the sampled images and the accuracy of the extraction process.","correct":false,"id":"F"},{"text":"Let each reviewer choose an unstated damage threshold","why":"Consistent criteria make the derived labels interpretable and comparable.","correct":false,"id":"G"},{"text":"Define what counts as damage before labelling images","why":"Consistent criteria make the derived labels interpretable and comparable.","correct":true,"id":"H"}],"answer":"Consistent criteria make the derived labels interpretable and comparable. The label is a derived interpretation, not an original verified tabular field. Processing volume does not measure the quality of the classifications. Conclusions depend on the sampled images and the accuracy of the extraction process.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q08"},{"ksb":"K5","objective":"Numeric-looking categories","prompt":"A service records categories as 1, 2 and 9, where 9 means unknown. Which interpretations are valid?","options":[{"text":"Count categories with a clear treatment of unknowns","why":"Category frequencies can be meaningful while numerical distances between these labels are not.","correct":true,"id":"A"},{"text":"Convert the labels to integers to establish equal intervals","why":"Storage type and sorting order do not establish a measurement scale.","correct":false,"id":"B"},{"text":"Treat 9 as nine times the quantity represented by 1","why":"The codebook identifies an unknown category rather than a numerical magnitude.","correct":false,"id":"C"},{"text":"Include code 9 in a continuous distribution without explanation","why":"Category frequencies can be meaningful while numerical distances between these labels are not.","correct":false,"id":"D"},{"text":"Infer ordering from the ascending code values","why":"Storage type and sorting order do not establish a measurement scale.","correct":false,"id":"E"},{"text":"Treat the codes as labels unless their meaning specifies a scale","why":"Arbitrary category codes do not become meaningful measurements merely because they are numbers.","correct":true,"id":"F"},{"text":"Apply the documented meaning of code 9","why":"The codebook identifies an unknown category rather than a numerical magnitude.","correct":true,"id":"G"},{"text":"Report their average as the typical service category","why":"Arbitrary category codes do not become meaningful measurements merely because they are numbers.","correct":false,"id":"H"}],"answer":"Arbitrary category codes do not become meaningful measurements merely because they are numbers. The codebook identifies an unknown category rather than a numerical magnitude. Category frequencies can be meaningful while numerical distances between these labels are not. Storage type and sorting order do not establish a measurement scale.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q09"},{"ksb":"K5","objective":"Dates stored as text","prompt":"A spreadsheet contains ISO dates and free-text entries such as 'next Tuesday'. Which decisions recognise the structural difference?","options":[{"text":"Apply one date parser and accept every returned value","why":"A parser's output still needs checking against the source convention and ambiguous entries.","correct":false,"id":"A"},{"text":"Flag unresolved entries rather than invent precise dates","why":"Inventing a default precise date can misrepresent unknown timing.","correct":true,"id":"B"},{"text":"Declare every cell reliable because the column is labelled Date","why":"Mixed content needs field-level assessment rather than a blanket conclusion from the column label.","correct":false,"id":"C"},{"text":"Parse standard dates with a defined format","why":"A parser's output still needs checking against the source convention and ambiguous entries.","correct":true,"id":"D"},{"text":"Replace every unresolved phrase with the month end","why":"Inventing a default precise date can misrepresent unknown timing.","correct":false,"id":"E"},{"text":"Resolve relative phrases using a documented reference date","why":"A relative phrase needs its original reference context, not an arbitrary execution date.","correct":true,"id":"F"},{"text":"Interpret 'next Tuesday' from the day you happen to run the analysis","why":"A relative phrase needs its original reference context, not an arbitrary execution date.","correct":false,"id":"G"},{"text":"Declare every cell unstructured because some entries are narrative","why":"Mixed content needs field-level assessment rather than a blanket conclusion from the column label.","correct":false,"id":"H"}],"answer":"A parser's output still needs checking against the source convention and ambiguous entries. A relative phrase needs its original reference context, not an arbitrary execution date. Inventing a default precise date can misrepresent unknown timing. Mixed content needs field-level assessment rather than a blanket conclusion from the column label.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T15-E2-Q10"}]},{"id":"T16","title":"K6 · Data Structures & Database System Design","description":"Storage types, relational design, pipelines and maintenance.","questions":[{"ksb":"K6","objective":"Relational transactions","prompt":"An application must transfer a reservation from one slot to another without leaving both booked. Which database principles are relevant?","options":[{"text":"Treat successful execution once as proof of atomic behaviour","why":"The required all-or-nothing behaviour needs relevant failure checks, not just one successful path.","correct":false,"id":"A"},{"text":"Commit the first change and rely only on a later manual check","why":"A transaction can protect the consistency of related changes when one step fails.","correct":false,"id":"B"},{"text":"Assume a single-user test proves multi-user correctness","why":"Concurrent activity can expose conflicts absent from a single-user run.","correct":false,"id":"C"},{"text":"Consider concurrent updates to the same slots","why":"Concurrent activity can expose conflicts absent from a single-user run.","correct":true,"id":"D"},{"text":"Group the related changes into an appropriate transaction","why":"A transaction can protect the consistency of related changes when one step fails.","correct":true,"id":"E"},{"text":"Test failure and recovery behaviour","why":"The required all-or-nothing behaviour needs relevant failure checks, not just one successful path.","correct":true,"id":"F"},{"text":"Define constraints that reflect the booking rules","why":"Appropriate database constraints address invalid states closer to where they are created.","correct":true,"id":"G"},{"text":"Depend solely on the chart to reveal conflicting bookings","why":"Appropriate database constraints address invalid states closer to where they are created.","correct":false,"id":"H"}],"answer":"A transaction can protect the consistency of related changes when one step fails. Appropriate database constraints address invalid states closer to where they are created. Concurrent activity can expose conflicts absent from a single-user run. The required all-or-nothing behaviour needs relevant failure checks, not just one successful path.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q01"},{"ksb":"K6","objective":"Data lake governance","prompt":"A platform stores raw CSV, JSON and images in a lake. Analysts struggle to find their meaning and owners. Which improvements address the problem?","options":[{"text":"Record provenance and processing state","why":"Successful storage does not establish quality, origin or whether data is raw or processed.","correct":true,"id":"A"},{"text":"Treat all files as equally validated because storage succeeded","why":"Successful storage does not establish quality, origin or whether data is raw or processed.","correct":false,"id":"B"},{"text":"Add ownership and discoverable metadata","why":"Discovery and responsibility require metadata and ownership, not merely a common extension.","correct":true,"id":"C"},{"text":"Defer controls until data enters a warehouse","why":"A lake still contains information requiring governance before any later transformation.","correct":false,"id":"D"},{"text":"Allow unlimited copies to compensate for missing ownership","why":"Folder labels and duplication do not resolve undocumented meaning or accountability.","correct":false,"id":"E"},{"text":"Convert every file to a spreadsheet as the only governance measure","why":"Discovery and responsibility require metadata and ownership, not merely a common extension.","correct":false,"id":"F"},{"text":"Apply access and retention controls to the stored objects","why":"A lake still contains information requiring governance before any later transformation.","correct":true,"id":"G"},{"text":"Infer meaning exclusively from folder names","why":"Folder labels and duplication do not resolve undocumented meaning or accountability.","correct":false,"id":"H"}],"answer":"Discovery and responsibility require metadata and ownership, not merely a common extension. Successful storage does not establish quality, origin or whether data is raw or processed. A lake still contains information requiring governance before any later transformation. Folder labels and duplication do not resolve undocumented meaning or accountability.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q02"},{"ksb":"K6","objective":"Maintenance responsibilities","prompt":"You query a managed database; another team owns backups, patching and schema changes. Which account of system maintenance is accurate?","options":[{"text":"Infer successful recovery merely from the existence of backup files","why":"Recovery and currency require appropriate evidence; file existence and connectivity alone do not establish them.","correct":false,"id":"A"},{"text":"Explain how validated loads and access roles affect your analysis","why":"Database operation involves data loads, permissions and other system responsibilities beyond the desktop device.","correct":true,"id":"B"},{"text":"Infer current data merely from a successful connection","why":"Recovery and currency require appropriate evidence; file existence and connectivity alone do not establish them.","correct":false,"id":"C"},{"text":"Limit maintenance to replacing broken desktop monitors","why":"Database operation involves data loads, permissions and other system responsibilities beyond the desktop device.","correct":false,"id":"D"},{"text":"Attribute the platform team's backup work to your own SQL activity","why":"Understanding maintenance does not justify claiming actions performed by others.","correct":false,"id":"E"},{"text":"Alter the production schema because your report would be easier","why":"A consumer's analytical need does not itself grant authority to change production design.","correct":false,"id":"F"},{"text":"Describe the maintenance responsibilities of the platform team","why":"Understanding maintenance does not justify claiming actions performed by others.","correct":true,"id":"G"},{"text":"Describe the authorised way to request a schema change","why":"A consumer's analytical need does not itself grant authority to change production design.","correct":true,"id":"H"}],"answer":"Understanding maintenance does not justify claiming actions performed by others. Database operation involves data loads, permissions and other system responsibilities beyond the desktop device. A consumer's analytical need does not itself grant authority to change production design. Recovery and currency require appropriate evidence; file existence and connectivity alone do not establish them.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q03"},{"ksb":"K6","objective":"Primary and foreign keys","prompt":"Orders contain order_id and customer_id. Customers contains one row per customer. Which design statements are justified?","options":[{"text":"customer_id must be unique in Orders even when customers place several orders","why":"Repeated customer references are consistent with a one-to-many relationship.","correct":false,"id":"A"},{"text":"Orders.customer_id can reference Customers.customer_id","why":"A foreign key represents a specified relationship rather than a popularity rule.","correct":true,"id":"B"},{"text":"A foreign key is whichever field has the most distinct values","why":"A foreign key represents a specified relationship rather than a popularity rule.","correct":false,"id":"C"},{"text":"Treat matching column labels as proof that a constraint exists","why":"Display order and naming do not create a stable enforced relationship.","correct":false,"id":"D"},{"text":"Accept an unknown customer reference merely because its type is numeric","why":"A valid data type does not establish that the referenced customer exists.","correct":false,"id":"E"},{"text":"Use row display position as a permanent customer relationship","why":"Display order and naming do not create a stable enforced relationship.","correct":false,"id":"F"},{"text":"Enforce appropriate referential integrity","why":"A valid data type does not establish that the referenced customer exists.","correct":true,"id":"G"},{"text":"order_id can identify each order uniquely","why":"Repeated customer references are consistent with a one-to-many relationship.","correct":true,"id":"H"}],"answer":"Repeated customer references are consistent with a one-to-many relationship. A foreign key represents a specified relationship rather than a popularity rule. A valid data type does not establish that the referenced customer exists. Display order and naming do not create a stable enforced relationship.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q04"},{"ksb":"K6","objective":"Schema change","prompt":"A source adds a new status value. The reporting pipeline accepts only the previous values. Which maintenance actions are appropriate?","options":[{"text":"Disable all validation to make the next load pass","why":"A targeted, tested change is preferable to losing controls on unrelated data.","correct":false,"id":"A"},{"text":"Update validation and affected transformations through change control","why":"A targeted, tested change is preferable to losing controls on unrelated data.","correct":true,"id":"B"},{"text":"Check only that the source database starts successfully","why":"The change can affect dependent calculations and reports even when the source operates normally.","correct":false,"id":"C"},{"text":"Retain a traceable migration and rollback approach where appropriate","why":"Controlled change records support recovery and explanation if the new mapping causes problems.","correct":true,"id":"D"},{"text":"Map it to the most frequent old status without agreement","why":"A new business state needs a confirmed interpretation rather than a convenient replacement.","correct":false,"id":"E"},{"text":"Confirm the meaning of the new status with its owner","why":"A new business state needs a confirmed interpretation rather than a convenient replacement.","correct":true,"id":"F"},{"text":"Apply the change directly and discard the previous schema definition","why":"Controlled change records support recovery and explanation if the new mapping causes problems.","correct":false,"id":"G"},{"text":"Test downstream reports and consumers","why":"The change can affect dependent calculations and reports even when the source operates normally.","correct":true,"id":"H"}],"answer":"A new business state needs a confirmed interpretation rather than a convenient replacement. A targeted, tested change is preferable to losing controls on unrelated data. The change can affect dependent calculations and reports even when the source operates normally. Controlled change records support recovery and explanation if the new mapping causes problems.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q05"},{"ksb":"K6","objective":"NoSQL trade-off","prompt":"A product catalogue has nested attributes that vary by product type. A document store is proposed. Which explanation is balanced?","options":[{"text":"Nested documents may fit the varying product attributes","why":"Flexible representation still needs decisions about validation and meaning.","correct":true,"id":"A"},{"text":"Select NoSQL solely because it is described as modern","why":"Suitability depends on the actual access and maintenance requirements.","correct":false,"id":"B"},{"text":"Claim relational systems cannot store any nested information","why":"Neither limitation nor uniqueness guarantee follows simply from the database category.","correct":false,"id":"C"},{"text":"Claim a document store automatically prevents duplicate product records","why":"Neither limitation nor uniqueness guarantee follows simply from the database category.","correct":false,"id":"D"},{"text":"Assume every NoSQL product has identical consistency behaviour","why":"NoSQL covers different systems with different characteristics and trade-offs.","correct":false,"id":"E"},{"text":"Evaluate query and update patterns before choosing the store","why":"Suitability depends on the actual access and maintenance requirements.","correct":true,"id":"F"},{"text":"Consider consistency, relationships and operational constraints","why":"NoSQL covers different systems with different characteristics and trade-offs.","correct":true,"id":"G"},{"text":"Document storage removes the need to define expected content","why":"Flexible representation still needs decisions about validation and meaning.","correct":false,"id":"H"}],"answer":"Flexible representation still needs decisions about validation and meaning. Suitability depends on the actual access and maintenance requirements. NoSQL covers different systems with different characteristics and trade-offs. Neither limitation nor uniqueness guarantee follows simply from the database category.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q06"},{"ksb":"K6","objective":"ETL and ELT","prompt":"Workflow A transforms extracted records before loading the target. Workflow B loads raw records and transforms them in the target platform. Which descriptions are correct?","options":[{"text":"Workflow B follows ELT ordering","why":"In B, loading precedes transformation, which is the defining order described here.","correct":true,"id":"A"},{"text":"Workflow A follows ETL ordering","why":"Both begin with extraction; the relative positions of transformation and loading distinguish them.","correct":true,"id":"B"},{"text":"Tool choice depends on source, target and operational constraints","why":"The appropriate approach depends on capabilities and requirements rather than the acronym alone.","correct":true,"id":"C"},{"text":"Only the workflow with earlier transformation needs governance","why":"Processing order does not remove the need for suitable controls.","correct":false,"id":"D"},{"text":"ELT is universally superior regardless of the platform","why":"The appropriate approach depends on capabilities and requirements rather than the acronym alone.","correct":false,"id":"E"},{"text":"Both workflows need quality and access controls","why":"Processing order does not remove the need for suitable controls.","correct":true,"id":"F"},{"text":"Workflow A is ELT because extraction comes first","why":"Both begin with extraction; the relative positions of transformation and loading distinguish them.","correct":false,"id":"G"},{"text":"Workflow B is ETL because it eventually transforms data","why":"In B, loading precedes transformation, which is the defining order described here.","correct":false,"id":"H"}],"answer":"Both begin with extraction; the relative positions of transformation and loading distinguish them. In B, loading precedes transformation, which is the defining order described here. Processing order does not remove the need for suitable controls. The appropriate approach depends on capabilities and requirements rather than the acronym alone.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q07"},{"ksb":"K6","objective":"API and BI access","prompt":"A BI tool retrieves data through an authenticated API backed by a database. Which statements describe the components accurately?","options":[{"text":"Check pagination and extraction limits","why":"A response can represent only one page or a limited subset.","correct":true,"id":"A"},{"text":"Treat the first successful response as the entire dataset","why":"A response can represent only one page or a limited subset.","correct":false,"id":"B"},{"text":"Claim using the BI connector proves database administration experience","why":"Consuming data does not prove platform administration, and transformation location depends on the actual workflow.","correct":false,"id":"C"},{"text":"Authentication and authorisation constrain retrieval","why":"Knowing an address does not establish an authorised identity or data entitlement.","correct":true,"id":"D"},{"text":"The API provides an interface to permitted operations or data","why":"An access interface and the underlying storage system have distinct roles.","correct":true,"id":"E"},{"text":"Assume all transformations occur inside the database","why":"Consuming data does not prove platform administration, and transformation location depends on the actual workflow.","correct":false,"id":"F"},{"text":"Possessing the endpoint URL establishes permission for all records","why":"Knowing an address does not establish an authorised identity or data entitlement.","correct":false,"id":"G"},{"text":"The API is necessarily the database's physical storage engine","why":"An access interface and the underlying storage system have distinct roles.","correct":false,"id":"H"}],"answer":"An access interface and the underlying storage system have distinct roles. Knowing an address does not establish an authorised identity or data entitlement. A response can represent only one page or a limited subset. Consuming data does not prove platform administration, and transformation location depends on the actual workflow.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q08"},{"ksb":"K6","objective":"Warehouse purpose","prompt":"A team needs integrated monthly reporting across three operational systems with historical comparisons. Which architecture explanations fit a warehouse?","options":[{"text":"Treat each current application screen as a complete historical store","why":"Operational views may not retain the integrated historical information required for reporting.","correct":false,"id":"A"},{"text":"Design suitable loads and historical handling","why":"Historical comparisons require an explicit approach to changes and retained history.","correct":true,"id":"B"},{"text":"Assume a central warehouse makes every source field public internally","why":"Centralisation does not remove access controls or the need to define refresh arrangements.","correct":false,"id":"C"},{"text":"Assume identical column names establish shared business definitions","why":"Integration needs semantic alignment, not just matching names.","correct":false,"id":"D"},{"text":"Define consistent dimensions and measures across sources","why":"Integration needs semantic alignment, not just matching names.","correct":true,"id":"E"},{"text":"Control access and refresh expectations for consumers","why":"Centralisation does not remove access controls or the need to define refresh arrangements.","correct":true,"id":"F"},{"text":"Integrate relevant sources for analytical use","why":"Operational views may not retain the integrated historical information required for reporting.","correct":true,"id":"G"},{"text":"Overwrite every historical value without checking reporting needs","why":"Historical comparisons require an explicit approach to changes and retained history.","correct":false,"id":"H"}],"answer":"Operational views may not retain the integrated historical information required for reporting. Integration needs semantic alignment, not just matching names. Historical comparisons require an explicit approach to changes and retained history. Centralisation does not remove access controls or the need to define refresh arrangements.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q09"},{"ksb":"K6","objective":"Normalisation","prompt":"A table repeats a supplier's address on every order. Updating only some rows creates conflicting addresses. Which design decisions address this problem?","options":[{"text":"Link orders through whichever address text is shortest","why":"A stable entity key is more appropriate than an arbitrary address-string rule.","correct":false,"id":"A"},{"text":"Remove all historical order rows after an address change","why":"Removing transactions or merging distinct suppliers does not provide a sound entity design.","correct":false,"id":"B"},{"text":"Keep one address copy per order and rely on visual review","why":"Separating shared supplier attributes reduces the repeated updates that caused the inconsistency.","correct":false,"id":"C"},{"text":"Describe normalisation as rescaling numerical columns","why":"Database normalisation concerns dependencies and duplication, not numerical scaling.","correct":false,"id":"D"},{"text":"Combine unrelated suppliers that share a postcode","why":"Removing transactions or merging distinct suppliers does not provide a sound entity design.","correct":false,"id":"E"},{"text":"Explain the update anomaly and intended relationships","why":"Database normalisation concerns dependencies and duplication, not numerical scaling.","correct":true,"id":"F"},{"text":"Link orders through an appropriate supplier key","why":"A stable entity key is more appropriate than an arbitrary address-string rule.","correct":true,"id":"G"},{"text":"Store supplier attributes in a supplier entity","why":"Separating shared supplier attributes reduces the repeated updates that caused the inconsistency.","correct":true,"id":"H"}],"answer":"Separating shared supplier attributes reduces the repeated updates that caused the inconsistency. A stable entity key is more appropriate than an arbitrary address-string rule. Database normalisation concerns dependencies and duplication, not numerical scaling. Removing transactions or merging distinct suppliers does not provide a sound entity design.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T16-E2-Q10"}]},{"id":"T17","title":"K7 · User Experience (UX) & Domain Context Principles","description":"Task-focused UX, domain definitions and accessible interpretation.","questions":[{"ksb":"K7","objective":"Open-case interpretation","prompt":"A completion-time chart includes open cases as zero days. Which domain and UX concerns should be addressed?","options":[{"text":"Provide a suitable view of current open workload","why":"Completed durations and current workload answer different operational questions.","correct":true,"id":"A"},{"text":"Separate open cases from completed durations","why":"A case without a completed duration should not silently become a completed zero-day case.","correct":true,"id":"B"},{"text":"Show the population and treatment of open cases","why":"The viewer needs to know what the metric represents and which cases contribute.","correct":true,"id":"C"},{"text":"Use the completed-case average as a direct count of open demand","why":"Completed durations and current workload answer different operational questions.","correct":false,"id":"D"},{"text":"Treat the correction as wording only","why":"Altering which values enter the average can materially change the metric.","correct":false,"id":"E"},{"text":"Keep zeros because they make every record numeric","why":"A case without a completed duration should not silently become a completed zero-day case.","correct":false,"id":"F"},{"text":"Check how the corrected treatment changes the reported result","why":"Altering which values enter the average can materially change the metric.","correct":true,"id":"G"},{"text":"Label the average simply 'all cases' without explaining exclusions","why":"The viewer needs to know what the metric represents and which cases contribute.","correct":false,"id":"H"}],"answer":"A case without a completed duration should not silently become a completed zero-day case. The viewer needs to know what the metric represents and which cases contribute. Completed durations and current workload answer different operational questions. Altering which values enter the average can materially change the metric.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q01"},{"ksb":"K7","objective":"Accessibility claim","prompt":"A team adopts a pleasing palette and declares its dashboard accessible. Which additional checks are relevant?","options":[{"text":"State the standards checked and remaining limitations","why":"A limited review supports only the checks actually performed.","correct":true,"id":"A"},{"text":"Check contrast, text readability and non-colour meaning","why":"Aesthetic preference is not evidence that information is perceivable.","correct":true,"id":"B"},{"text":"Treat successful mouse use as sufficient interaction testing","why":"Keyboard access needs its own practical checks for users who do not use a mouse.","correct":false,"id":"C"},{"text":"Claim complete conformance from a single palette review","why":"A limited review supports only the checks actually performed.","correct":false,"id":"D"},{"text":"Check suitable alternatives for charts and meaningful control labels","why":"A title can identify a chart but may not communicate its values or findings; labels and alternatives must serve the user's information need.","correct":true,"id":"E"},{"text":"Assume visual attractiveness establishes readable contrast","why":"Aesthetic preference is not evidence that information is perceivable.","correct":false,"id":"F"},{"text":"Check keyboard operation for essential interactions","why":"Keyboard access needs its own practical checks for users who do not use a mouse.","correct":true,"id":"G"},{"text":"Use the chart's title as its full text alternative even when the values are unavailable elsewhere","why":"A title can identify a chart but may not communicate its values or findings; labels and alternatives must serve the user's information need.","correct":false,"id":"H"}],"answer":"Keyboard access needs its own practical checks for users who do not use a mouse. Aesthetic preference is not evidence that information is perceivable. A title can identify a chart but may not communicate its values or findings; labels and alternatives must serve the user's information need. A limited review supports only the checks actually performed.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q02"},{"ksb":"K7","objective":"Non-colour cues","prompt":"A chart uses only red and green lines to distinguish two services. Which changes improve access without losing the comparison?","options":[{"text":"Offer a suitable data table or text alternative","why":"An alternative should communicate the relevant values or insight, rather than simply announce the comparison.","correct":true,"id":"A"},{"text":"Provide meaningful labels or a clear legend","why":"A user needs an unambiguous way to identify what each line represents.","correct":true,"id":"B"},{"text":"Add distinct line styles or markers","why":"Additional non-colour cues help people distinguish series even when colours are not discriminable.","correct":true,"id":"C"},{"text":"Change the shades but retain colour as the only identifier","why":"Additional non-colour cues help people distinguish series even when colours are not discriminable.","correct":false,"id":"D"},{"text":"Assume any saturated colour has sufficient contrast","why":"Contrast depends on the actual colour combination and presentation.","correct":false,"id":"E"},{"text":"Check contrast in the actual background and text context","why":"Contrast depends on the actual colour combination and presentation.","correct":true,"id":"F"},{"text":"Use identical abbreviated labels for both series","why":"A user needs an unambiguous way to identify what each line represents.","correct":false,"id":"G"},{"text":"Provide a caption saying that two services are compared without conveying their values or differences","why":"An alternative should communicate the relevant values or insight, rather than simply announce the comparison.","correct":false,"id":"H"}],"answer":"Additional non-colour cues help people distinguish series even when colours are not discriminable. A user needs an unambiguous way to identify what each line represents. Contrast depends on the actual colour combination and presentation. An alternative should communicate the relevant values or insight, rather than simply announce the comparison.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q03"},{"ksb":"K7","objective":"Progressive detail","prompt":"Executives need a brief overview, while analysts need detailed breakdowns of the same measures. Which UX approach supports both?","options":[{"text":"Infer analyst needs solely from executive feedback","why":"Different audiences may have different tasks requiring direct consideration.","correct":false,"id":"A"},{"text":"Require users to remember an undocumented keyboard shortcut","why":"Discoverable controls make the deeper view usable without hidden procedural knowledge.","correct":false,"id":"B"},{"text":"Make drill-down and return actions discoverable","why":"Discoverable controls make the deeper view usable without hidden procedural knowledge.","correct":true,"id":"C"},{"text":"Provide a clear overview with access to relevant detail","why":"An overview can reduce cognitive load while preserving a route to detailed analysis.","correct":true,"id":"D"},{"text":"Use different denominator definitions without signalling the change","why":"Consistent meaning is necessary for users to connect overview and detail correctly.","correct":false,"id":"E"},{"text":"Keep definitions consistent across levels","why":"Consistent meaning is necessary for users to connect overview and detail correctly.","correct":true,"id":"F"},{"text":"Show every row on the opening screen for all audiences","why":"An overview can reduce cognitive load while preserving a route to detailed analysis.","correct":false,"id":"G"},{"text":"Test the flow with both audience types","why":"Different audiences may have different tasks requiring direct consideration.","correct":true,"id":"H"}],"answer":"An overview can reduce cognitive load while preserving a route to detailed analysis. Consistent meaning is necessary for users to connect overview and detail correctly. Discoverable controls make the deeper view usable without hidden procedural knowledge. Different audiences may have different tasks requiring direct consideration.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q04"},{"ksb":"K7","objective":"Audience vocabulary","prompt":"A dashboard for new service managers uses unexplained database column names. Which design decisions support understanding?","options":[{"text":"Replace an undefined operational measure with a different familiar one","why":"Simplification should not silently change the statistical or business meaning.","correct":false,"id":"A"},{"text":"Use terms the managers recognise and define technical measures","why":"User-facing labels should support the audience's interpretation while preserving accurate meaning.","correct":true,"id":"B"},{"text":"Simplify 'median' to 'average' without specifying the statistic","why":"Simplification should not silently change the statistical or business meaning.","correct":false,"id":"C"},{"text":"Keep units and time windows visible","why":"Relevant context needs to be available where users interpret the output.","correct":true,"id":"D"},{"text":"Put every measure definition only in an inaccessible source file","why":"Relevant context needs to be available where users interpret the output.","correct":false,"id":"E"},{"text":"Check ambiguous terms with domain owners","why":"Domain validation helps prevent readable but inaccurate labels.","correct":true,"id":"F"},{"text":"Retain source-field abbreviations solely for developer convenience","why":"User-facing labels should support the audience's interpretation while preserving accurate meaning.","correct":false,"id":"G"},{"text":"Choose familiar-sounding labels without confirming their meaning","why":"Domain validation helps prevent readable but inaccurate labels.","correct":false,"id":"H"}],"answer":"User-facing labels should support the audience's interpretation while preserving accurate meaning. Relevant context needs to be available where users interpret the output. Domain validation helps prevent readable but inaccurate labels. Simplification should not silently change the statistical or business meaning.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q05"},{"ksb":"K7","objective":"Prototype evidence","prompt":"A prototype review finds that users repeatedly mistake a monthly total for a cumulative one. Which response demonstrates UX informed by domain context?","options":[{"text":"Check whether the visual form implies accumulation","why":"Chart form and context can influence how a time-based measure is interpreted.","correct":true,"id":"A"},{"text":"Delete the period labels to make the view look simpler","why":"An unagreed measure change or removal of context does not solve the user's interpretation need reliably.","correct":false,"id":"B"},{"text":"Clarify the time basis in the label and surrounding context","why":"Correct calculation does not prevent an unclear presentation from producing a wrong interpretation.","correct":true,"id":"C"},{"text":"Assume every line chart is understood identically","why":"Chart form and context can influence how a time-based measure is interpreted.","correct":false,"id":"D"},{"text":"Keep the label because the formula is technically correct","why":"Correct calculation does not prevent an unclear presentation from producing a wrong interpretation.","correct":false,"id":"E"},{"text":"Retest the revised design against the same interpretation task","why":"A task-based retest can show whether the actual misunderstanding was addressed.","correct":true,"id":"F"},{"text":"Change the calculation to cumulative without confirming the requirement","why":"An unagreed measure change or removal of context does not solve the user's interpretation need reliably.","correct":false,"id":"G"},{"text":"Count a changed colour as proof the misunderstanding is resolved","why":"A task-based retest can show whether the actual misunderstanding was addressed.","correct":false,"id":"H"}],"answer":"Correct calculation does not prevent an unclear presentation from producing a wrong interpretation. Chart form and context can influence how a time-based measure is interpreted. A task-based retest can show whether the actual misunderstanding was addressed. An unagreed measure change or removal of context does not solve the user's interpretation need reliably.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q06"},{"ksb":"K7","objective":"Domain consequences","prompt":"A service dashboard ranks teams by raw completed-case counts. Teams handle different case complexity and staffing. Which design considerations are justified?","options":[{"text":"Optimise the ranking solely for a dramatic visual contrast","why":"Comparison design should serve a meaningful decision rather than exaggerate differences.","correct":false,"id":"A"},{"text":"Put qualifications only in a separate document users rarely open","why":"Material limits should be available at the point where the ranking could be misinterpreted.","correct":false,"id":"B"},{"text":"Make limitations visible near the ranking","why":"Material limits should be available at the point where the ranking could be misinterpreted.","correct":true,"id":"C"},{"text":"Explain relevant workload and staffing context","why":"Raw counts can reflect workload and resources as well as effort.","correct":true,"id":"D"},{"text":"Present the ranking as a direct measure of individual effort","why":"Raw counts can reflect workload and resources as well as effort.","correct":false,"id":"E"},{"text":"Infer low quality from a lower raw completion count","why":"Neither the count nor the chart geometry establishes those operational conclusions.","correct":false,"id":"F"},{"text":"Choose comparisons aligned with the stakeholder's decision","why":"Comparison design should serve a meaningful decision rather than exaggerate differences.","correct":true,"id":"G"},{"text":"Infer equal capacity from equal column widths","why":"Neither the count nor the chart geometry establishes those operational conclusions.","correct":false,"id":"H"}],"answer":"Raw counts can reflect workload and resources as well as effort. Comparison design should serve a meaningful decision rather than exaggerate differences. Material limits should be available at the point where the ranking could be misinterpreted. Neither the count nor the chart geometry establishes those operational conclusions.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q07"},{"ksb":"K7","objective":"Filter state","prompt":"A stakeholder screenshots a dashboard after applying a regional filter. The image does not show that filter. Which UX improvements reduce misinterpretation?","options":[{"text":"Show filters only in a panel excluded from exports","why":"A screenshot or exported view needs enough context to remain interpretable outside the application.","correct":false,"id":"A"},{"text":"Include the relevant reporting period","why":"Export time and the period represented by the data are different pieces of context.","correct":true,"id":"B"},{"text":"Ensure exported views retain essential filter information","why":"A screenshot or exported view needs enough context to remain interpretable outside the application.","correct":true,"id":"C"},{"text":"Display the active region alongside the measures","why":"The selected context should be explicit rather than guessed from results.","correct":true,"id":"D"},{"text":"Remove the filter control but leave the filtered values","why":"Hiding a control or changing a title does not make a subset represent the full population.","correct":false,"id":"E"},{"text":"Relabel the filtered result as the whole organisation","why":"Hiding a control or changing a title does not make a subset represent the full population.","correct":false,"id":"F"},{"text":"Use the export date as though it were the data period","why":"Export time and the period represented by the data are different pieces of context.","correct":false,"id":"G"},{"text":"Assume recipients can infer the filter from the values","why":"The selected context should be explicit rather than guessed from results.","correct":false,"id":"H"}],"answer":"The selected context should be explicit rather than guessed from results. Export time and the period represented by the data are different pieces of context. A screenshot or exported view needs enough context to remain interpretable outside the application. Hiding a control or changing a title does not make a subset represent the full population.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q08"},{"ksb":"K7","objective":"Decision hierarchy","prompt":"A duty manager has thirty seconds to identify which service needs attention. The dashboard gives equal prominence to twenty metrics. Which UX changes address the task?","options":[{"text":"Group related measures and explain the threshold","why":"Grouping and explicit thresholds support interpretation without requiring the viewer to infer a colour meaning.","correct":true,"id":"A"},{"text":"Judge usability only by the designer's preference","why":"Task-based review provides evidence about the intended user's experience.","correct":false,"id":"B"},{"text":"Test whether the manager can locate the relevant exception","why":"Task-based review provides evidence about the intended user's experience.","correct":true,"id":"C"},{"text":"Add an animation to every changing metric","why":"A time-critical exception task needs a clear route to the relevant information; extra presentation barriers and competing motion delay that task.","correct":false,"id":"D"},{"text":"Replace threshold labels with unexplained colour gradients","why":"Grouping and explicit thresholds support interpretation without requiring the viewer to infer a colour meaning.","correct":false,"id":"E"},{"text":"Prioritise the measures that trigger the manager's decision","why":"Visual hierarchy should distinguish decision-critical information rather than preserve equal emphasis.","correct":true,"id":"F"},{"text":"Enlarge all twenty metrics equally","why":"Visual hierarchy should distinguish decision-critical information rather than preserve equal emphasis.","correct":false,"id":"G"},{"text":"Place the exception table after the full metric catalogue so readers encounter every measure first","why":"A time-critical exception task needs a clear route to the relevant information; extra presentation barriers and competing motion delay that task.","correct":false,"id":"H"}],"answer":"Visual hierarchy should distinguish decision-critical information rather than preserve equal emphasis. Grouping and explicit thresholds support interpretation without requiring the viewer to infer a colour meaning. Task-based review provides evidence about the intended user's experience. A time-critical exception task needs a clear route to the relevant information; extra presentation barriers and competing motion delay that task.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q09"},{"ksb":"K7","objective":"Domain definition","prompt":"A service promise uses working days. An analyst calculates calendar-day waiting times and labels them 'against target'. Which corrections are needed?","options":[{"text":"Compare both units directly against the same threshold without explanation","why":"The relationship depends on each interval and the applicable calendar, not one universal subtraction.","correct":false,"id":"A"},{"text":"Infer the working-day result by subtracting two days from every case","why":"The relationship depends on each interval and the applicable calendar, not one universal subtraction.","correct":false,"id":"B"},{"text":"Recalculate using the agreed calendar and exclusions","why":"Changing the label without the calculation misstates performance against the target.","correct":true,"id":"C"},{"text":"Explain the definition beside the measure","why":"A concise definition supports correct interpretation where the distinction affects decisions.","correct":true,"id":"D"},{"text":"Hide the definition to reduce visual clutter","why":"A concise definition supports correct interpretation where the distinction affects decisions.","correct":false,"id":"E"},{"text":"Confirm the service's working-day definition","why":"Available timestamps do not determine the business rule used by the service promise.","correct":true,"id":"F"},{"text":"Assume weekends count because the timestamps include them","why":"Available timestamps do not determine the business rule used by the service promise.","correct":false,"id":"G"},{"text":"Relabel calendar-day values as working days","why":"Changing the label without the calculation misstates performance against the target.","correct":false,"id":"H"}],"answer":"Available timestamps do not determine the business rule used by the service promise. Changing the label without the calculation misstates performance against the target. A concise definition supports correct interpretation where the distinction affects decisions. The relationship depends on each interval and the applicable calendar, not one universal subtraction.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."},"id":"T17-E2-Q10"}]},{"id":"T18","title":"K8 · Data Quality Risks","description":"Fitness for purpose, quality dimensions and reasoned treatment.","questions":[{"ksb":"K8","objective":"Conflicting definitions","prompt":"Two systems both contain 'resolved', but one includes withdrawn cases and the other does not. Which risks and responses are relevant?","options":[{"text":"Investigate the business meaning before combining counts","why":"Shared labels can conceal different inclusion rules.","correct":true,"id":"A"},{"text":"Document the effect of the chosen definition","why":"The mapping should reflect the decision need, not a preferred outcome.","correct":true,"id":"B"},{"text":"Treat identical labels as evidence of identical definitions","why":"Shared labels can conceal different inclusion rules.","correct":false,"id":"C"},{"text":"Agree a defensible mapping or present separate measures","why":"Type compatibility does not resolve a difference in the entities counted.","correct":true,"id":"D"},{"text":"Diagnose this solely as missing data","why":"Completeness and text formatting do not resolve the semantic inconsistency.","correct":false,"id":"E"},{"text":"Choose whichever definition gives the better performance result","why":"The mapping should reflect the decision need, not a preferred outcome.","correct":false,"id":"F"},{"text":"Combine the totals and explain only the column types","why":"Type compatibility does not resolve a difference in the entities counted.","correct":false,"id":"G"},{"text":"Fix the issue by changing both labels to uppercase","why":"Completeness and text formatting do not resolve the semantic inconsistency.","correct":false,"id":"H"}],"answer":"Shared labels can conceal different inclusion rules. Type compatibility does not resolve a difference in the entities counted. The mapping should reflect the decision need, not a preferred outcome. Completeness and text formatting do not resolve the semantic inconsistency.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q01"},{"ksb":"K8","objective":"Completeness denominator","prompt":"A field is populated for 180 of 200 records. The field is required for all 200. Which statements are correct?","options":[{"text":"Field completeness is 180% because 180 values exist","why":"The relevant proportion is 180 divided by the 200 expected values.","correct":false,"id":"A"},{"text":"Describe the 180 populated values as verified correct","why":"Presence and correctness are separate quality dimensions.","correct":false,"id":"B"},{"text":"Twenty required values are missing","why":"Missing values establish a completeness issue, not duplication of other records.","correct":true,"id":"C"},{"text":"Investigate whether missingness is concentrated in particular groups","why":"Systematic missingness could affect group comparisons and needs investigation.","correct":true,"id":"D"},{"text":"Twenty complete records must be duplicates","why":"Missing values establish a completeness issue, not duplication of other records.","correct":false,"id":"E"},{"text":"Distinguish field completeness from accuracy of populated values","why":"Presence and correctness are separate quality dimensions.","correct":true,"id":"F"},{"text":"Field completeness is 90% for these records","why":"The relevant proportion is 180 divided by the 200 expected values.","correct":true,"id":"G"},{"text":"Assume the missing values have the same distribution as observed values","why":"Systematic missingness could affect group comparisons and needs investigation.","correct":false,"id":"H"}],"answer":"The relevant proportion is 180 divided by the 200 expected values. Missing values establish a completeness issue, not duplication of other records. Systematic missingness could affect group comparisons and needs investigation. Presence and correctness are separate quality dimensions.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q02"},{"ksb":"K8","objective":"Suitable quality checks","prompt":"A report uses monetary totals and customer counts. Which checks address different quality risks?","options":[{"text":"Check customer identity at the intended counting grain","why":"Transaction and customer grains differ when customers make multiple transactions.","correct":true,"id":"A"},{"text":"Check currency and period definitions across sources","why":"Comparable totals require aligned units and time scope as well as types.","correct":true,"id":"B"},{"text":"Assume numeric types establish comparable amounts","why":"Comparable totals require aligned units and time scope as well as types.","correct":false,"id":"C"},{"text":"Treat a successful import as the complete quality review","why":"Import success and removal of missing records do not establish correct values or an unbiased population.","correct":false,"id":"D"},{"text":"Use row count alone to certify all monetary amounts","why":"The number of rows does not validate their monetary values.","correct":false,"id":"E"},{"text":"Treat removal of all blank rows as proof of accuracy","why":"Import success and removal of missing records do not establish correct values or an unbiased population.","correct":false,"id":"F"},{"text":"Count every transaction as a distinct customer","why":"Transaction and customer grains differ when customers make multiple transactions.","correct":false,"id":"G"},{"text":"Reconcile monetary totals against an appropriate source","why":"The number of rows does not validate their monetary values.","correct":true,"id":"H"}],"answer":"The number of rows does not validate their monetary values. Transaction and customer grains differ when customers make multiple transactions. Comparable totals require aligned units and time scope as well as types. Import success and removal of missing records do not establish correct values or an unbiased population.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q03"},{"ksb":"K8","objective":"Residual risk","prompt":"A source owner confirms that an historical field cannot be recovered before delivery. Which account of quality management is defensible?","options":[{"text":"Invent plausible values to maintain the original scope","why":"Unsupported values would create false precision rather than recover the missing information.","correct":false,"id":"A"},{"text":"Remove the issue from the log because repair is delayed","why":"The unresolved risk remains relevant to the output and future work.","correct":false,"id":"B"},{"text":"Stop all checks because one field is unrecoverable","why":"A limitation in one field does not remove the need to verify the remaining analysis.","correct":false,"id":"C"},{"text":"Agree an appropriate reduced scope or qualified output","why":"Unsupported values would create false precision rather than recover the missing information.","correct":true,"id":"D"},{"text":"Record the owner, decision and follow-up if applicable","why":"The unresolved risk remains relevant to the output and future work.","correct":true,"id":"E"},{"text":"Explain which conclusions the missing field limits","why":"Delivery does not change the unresolved quality limitation.","correct":true,"id":"F"},{"text":"State the dataset is fully complete because the report was delivered","why":"Delivery does not change the unresolved quality limitation.","correct":false,"id":"G"},{"text":"Validate the parts of the analysis that remain supportable","why":"A limitation in one field does not remove the need to verify the remaining analysis.","correct":true,"id":"H"}],"answer":"Delivery does not change the unresolved quality limitation. Unsupported values would create false precision rather than recover the missing information. The unresolved risk remains relevant to the output and future work. A limitation in one field does not remove the need to verify the remaining analysis.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q04"},{"ksb":"K8","objective":"NULL meaning","prompt":"A duration field is NULL for open cases and also for some failed imports. Which treatment is justified?","options":[{"text":"Apply one missing-value interpretation to every NULL","why":"The same missing marker can represent different underlying states.","correct":false,"id":"A"},{"text":"Distinguish not-yet-completed cases from import failures","why":"The same missing marker can represent different underlying states.","correct":true,"id":"B"},{"text":"Investigate failed imports with the source owner","why":"An import failure provides no basis for a zero-day completion value.","correct":true,"id":"C"},{"text":"Exclude all NULLs without checking the resulting population","why":"Exclusion can change the population and should be justified and described.","correct":false,"id":"D"},{"text":"Assign zero duration to failed imports to preserve the average","why":"An import failure provides no basis for a zero-day completion value.","correct":false,"id":"E"},{"text":"Recheck counts after a verified import repair","why":"The remaining data needs verification after the correction.","correct":true,"id":"F"},{"text":"Explain how the analysis handles each missingness reason","why":"Exclusion can change the population and should be justified and described.","correct":true,"id":"G"},{"text":"Assume successful repair of one record resolves every failure","why":"The remaining data needs verification after the correction.","correct":false,"id":"H"}],"answer":"The same missing marker can represent different underlying states. An import failure provides no basis for a zero-day completion value. Exclusion can change the population and should be justified and described. The remaining data needs verification after the correction.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q05"},{"ksb":"K8","objective":"Accuracy versus validity","prompt":"A record contains a validly formatted postcode, but the service user confirms it belongs to their previous address. Which conclusions are supported?","options":[{"text":"The value can pass a format check and still be inaccurate","why":"Validity of format does not establish agreement with the person's current circumstances.","correct":true,"id":"A"},{"text":"Treat the issue as irrelevant because no cells are blank","why":"A populated but incorrect value can distort geographical results.","correct":false,"id":"B"},{"text":"Assess which location-based outputs could be affected","why":"A populated but incorrect value can distort geographical results.","correct":true,"id":"C"},{"text":"Count the row as a uniqueness failure solely because the address is old","why":"An outdated address does not itself establish duplication, and a refresh need not verify each field.","correct":false,"id":"D"},{"text":"Replace the value with the most common postcode in the table","why":"A frequency-based replacement is not evidence of the individual's correct address.","correct":false,"id":"E"},{"text":"Treat the source system's recent refresh as proof this value was verified","why":"An outdated address does not itself establish duplication, and a refresh need not verify each field.","correct":false,"id":"F"},{"text":"Check the authorised source and correction route","why":"A frequency-based replacement is not evidence of the individual's correct address.","correct":true,"id":"G"},{"text":"Passing the postcode pattern proves the address is current","why":"Validity of format does not establish agreement with the person's current circumstances.","correct":false,"id":"H"}],"answer":"Validity of format does not establish agreement with the person's current circumstances. A frequency-based replacement is not evidence of the individual's correct address. A populated but incorrect value can distort geographical results. An outdated address does not itself establish duplication, and a refresh need not verify each field.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q06"},{"ksb":"K8","objective":"Impact and escalation","prompt":"Missing location data affects 2% of all cases but 35% of one small service's cases. Which response is appropriate?","options":[{"text":"Dismiss the issue using only the overall missing percentage","why":"Aggregate rates can hide a much larger problem in a decision-relevant subgroup.","correct":false,"id":"A"},{"text":"Allocate the missing cases proportionally without stating assumptions","why":"An allocation introduces assumptions and does not recover known locations.","correct":false,"id":"B"},{"text":"Escalate to the responsible data owner with quantified impact","why":"A targeted escalation should describe the issue and its consequences to the relevant owner.","correct":true,"id":"C"},{"text":"Send an unexplained list of blanks to an unrelated team","why":"A targeted escalation should describe the issue and its consequences to the relevant owner.","correct":false,"id":"D"},{"text":"Assess the effect on that service's comparison","why":"Aggregate rates can hide a much larger problem in a decision-relevant subgroup.","correct":true,"id":"E"},{"text":"Qualify or defer unsupported geographical conclusions","why":"An allocation introduces assumptions and does not recover known locations.","correct":true,"id":"F"},{"text":"Track the unresolved risk and agreed next steps","why":"Notification is a step towards resolution, not evidence that the data was corrected.","correct":true,"id":"G"},{"text":"Mark the issue resolved when an email is sent","why":"Notification is a step towards resolution, not evidence that the data was corrected.","correct":false,"id":"H"}],"answer":"Aggregate rates can hide a much larger problem in a decision-relevant subgroup. A targeted escalation should describe the issue and its consequences to the relevant owner. An allocation introduces assumptions and does not recover known locations. Notification is a step towards resolution, not evidence that the data was corrected.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q07"},{"ksb":"K8","objective":"Timeliness","prompt":"A weekly staffing decision uses a perfectly reconciled extract last refreshed eight weeks ago. Which quality conclusions are justified?","options":[{"text":"Define timeliness only by how quickly the chart renders","why":"Data currency and availability for the decision matter beyond interface speed.","correct":false,"id":"A"},{"text":"Fill recent weeks by copying the old totals without labelling estimates","why":"Unsupported copies would misrepresent observed information rather than resolve timeliness.","correct":false,"id":"B"},{"text":"Reconciled totals guarantee fitness for the current decision","why":"Accuracy checks do not resolve whether information is sufficiently current for its purpose.","correct":false,"id":"C"},{"text":"Check the expected refresh and source availability","why":"Data currency and availability for the decision matter beyond interface speed.","correct":true,"id":"D"},{"text":"Seek a suitable current source or qualify the decision","why":"Unsupported copies would misrepresent observed information rather than resolve timeliness.","correct":true,"id":"E"},{"text":"Explain the period represented and its limitation","why":"Download time does not change the age of the underlying observations.","correct":true,"id":"F"},{"text":"Label the old extract as current because it was downloaded today","why":"Download time does not change the age of the underlying observations.","correct":false,"id":"G"},{"text":"The extract may be too old for the staffing decision","why":"Accuracy checks do not resolve whether information is sufficiently current for its purpose.","correct":true,"id":"H"}],"answer":"Accuracy checks do not resolve whether information is sufficiently current for its purpose. Data currency and availability for the decision matter beyond interface speed. Download time does not change the age of the underlying observations. Unsupported copies would misrepresent observed information rather than resolve timeliness.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q08"},{"ksb":"K8","objective":"Outlier investigation","prompt":"One completed case took 190 days; most took under 20. Which actions assess the risk appropriately?","options":[{"text":"Check source dates and relevant case circumstances","why":"An extreme value can be valid and meaningful rather than erroneous.","correct":true,"id":"A"},{"text":"Winsorise the value to 20 and present it as observed","why":"A transformation should not be misrepresented as the original measurement.","correct":false,"id":"B"},{"text":"Keep only the statistic least affected and omit the investigation","why":"Robust summaries can help, but they do not replace checking the unusual record.","correct":false,"id":"C"},{"text":"Infer data entry error solely from distance from the mean","why":"Extremeness warrants investigation but does not alone establish either cause.","correct":false,"id":"D"},{"text":"Document any justified inclusion or correction","why":"A transformation should not be misrepresented as the original measurement.","correct":true,"id":"E"},{"text":"Examine the effect on summaries and the decision","why":"Robust summaries can help, but they do not replace checking the unusual record.","correct":true,"id":"F"},{"text":"Infer a recurring service problem from this single case alone","why":"Extremeness warrants investigation but does not alone establish either cause.","correct":false,"id":"G"},{"text":"Delete the case immediately because it is unusual","why":"An extreme value can be valid and meaningful rather than erroneous.","correct":false,"id":"H"}],"answer":"An extreme value can be valid and meaningful rather than erroneous. Robust summaries can help, but they do not replace checking the unusual record. A transformation should not be misrepresented as the original measurement. Extremeness warrants investigation but does not alone establish either cause.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q09"},{"ksb":"K8","objective":"Grain and uniqueness","prompt":"A table has one row per order line. order_id repeats when an order contains several products. Which checks address uniqueness correctly?","options":[{"text":"Check the intended order-line identifier or composite key","why":"Repetition of a parent order identifier is expected at order-line grain.","correct":true,"id":"A"},{"text":"Count order rows as distinct customers without checking relationships","why":"Changing grain changes what the records and totals represent.","correct":false,"id":"B"},{"text":"Treat every repeated order_id as an erroneous duplicate","why":"Repetition of a parent order identifier is expected at order-line grain.","correct":false,"id":"C"},{"text":"Explain the grain before interpreting duplicate counts","why":"A uniqueness check needs the intended unit, not an arbitrary column position.","correct":true,"id":"D"},{"text":"Report duplicate risk solely from the first column's distinct count","why":"A uniqueness check needs the intended unit, not an arbitrary column position.","correct":false,"id":"E"},{"text":"Deduplicate to one row per order and retain the original line-total label","why":"Changing grain changes what the records and totals represent.","correct":false,"id":"F"},{"text":"Compare apparent duplicate lines using relevant business fields","why":"A product can legitimately occur in different order lines and orders.","correct":true,"id":"G"},{"text":"Remove every repeated product code across all orders","why":"A product can legitimately occur in different order lines and orders.","correct":false,"id":"H"}],"answer":"Repetition of a parent order identifier is expected at order-line grain. A product can legitimately occur in different order lines and orders. A uniqueness check needs the intended unit, not an arbitrary column position. Changing grain changes what the records and totals represent.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T18-E2-Q10"}]},{"id":"T19","title":"K9 · Defining Customer Requirements","description":"Decision needs, stakeholder engagement, scope and acceptance criteria.","questions":[{"ksb":"K9","objective":"Traceability","prompt":"A customer asks why the final dashboard omits a requested filter. Which project records would support a defensible explanation?","options":[{"text":"A list of the developer's favourite features","why":"Scope decisions should connect to agreed needs and constraints rather than personal preference.","correct":false,"id":"A"},{"text":"Relevant review feedback and acceptance decisions","why":"Records of decisions and feedback explain the outcome more directly than meeting volume.","correct":true,"id":"B"},{"text":"A statement that omitted features were never requested","why":"A truthful account recognises the request and explains the agreed decision.","correct":false,"id":"C"},{"text":"A screenshot as proof that every requirement was met","why":"Traceable acceptance needs the agreed requirement and decision, not appearance or an invented assumption.","correct":false,"id":"D"},{"text":"The agreed priority and scope decision for that filter","why":"Scope decisions should connect to agreed needs and constraints rather than personal preference.","correct":true,"id":"E"},{"text":"The documented constraint or trade-off behind exclusion","why":"A truthful account recognises the request and explains the agreed decision.","correct":true,"id":"F"},{"text":"The number of meetings alone","why":"Records of decisions and feedback explain the outcome more directly than meeting volume.","correct":false,"id":"G"},{"text":"An undocumented assumption that all filters were optional","why":"Traceable acceptance needs the agreed requirement and decision, not appearance or an invented assumption.","correct":false,"id":"H"}],"answer":"Scope decisions should connect to agreed needs and constraints rather than personal preference. A truthful account recognises the request and explains the agreed decision. Records of decisions and feedback explain the outcome more directly than meeting volume. Traceable acceptance needs the agreed requirement and decision, not appearance or an invented assumption.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q01"},{"ksb":"K9","objective":"Decision before chart","prompt":"A sponsor requests 'a dashboard of delays' without saying what decision it should support. Which requirements questions should come first?","options":[{"text":"Promise every available measure before discussing priorities","why":"An observed average is not automatically an agreed operational target. Scope needs explicit priorities, definitions and decision criteria.","correct":false,"id":"A"},{"text":"Assume the existing export defines the entire requirement","why":"Available data does not establish the business problem or scope.","correct":false,"id":"B"},{"text":"Clarify which delays, population and period matter","why":"Available data does not establish the business problem or scope.","correct":true,"id":"C"},{"text":"Ask who will act on the result and how","why":"Audience and intended action guide what information the output needs to provide.","correct":true,"id":"D"},{"text":"Choose the chart types before identifying the users","why":"Audience and intended action guide what information the output needs to provide.","correct":false,"id":"E"},{"text":"Agree what a useful result would enable","why":"Delivery of a page is not the same as meeting the decision need.","correct":true,"id":"F"},{"text":"Use last month's average delay as the service target without confirming its meaning","why":"An observed average is not automatically an agreed operational target. Scope needs explicit priorities, definitions and decision criteria.","correct":false,"id":"G"},{"text":"Define success only as having a published dashboard URL","why":"Delivery of a page is not the same as meeting the decision need.","correct":false,"id":"H"}],"answer":"Audience and intended action guide what information the output needs to provide. Available data does not establish the business problem or scope. Delivery of a page is not the same as meeting the decision need. An observed average is not automatically an agreed operational target. Scope needs explicit priorities, definitions and decision criteria.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q02"},{"ksb":"K9","objective":"Conflicting priorities","prompt":"A director wants a high-level summary; an operational lead needs daily detail. Time permits one initial release. Which planning actions are appropriate?","options":[{"text":"Agree a prioritised first release and explicit exclusions","why":"A feasible plan needs an agreed boundary rather than unsupported commitments.","correct":true,"id":"A"},{"text":"Record the agreed trade-off and next review point","why":"Documenting the compromise reduces surprises and makes later changes manageable.","correct":true,"id":"B"},{"text":"Explore a shared overview with a suitable route to detail","why":"Shared measures can support different levels of detail without inconsistent meaning.","correct":true,"id":"C"},{"text":"Leave the decision implicit until delivery","why":"Documenting the compromise reduces surprises and makes later changes manageable.","correct":false,"id":"D"},{"text":"Promise both complete outputs without assessing effort","why":"A feasible plan needs an agreed boundary rather than unsupported commitments.","correct":false,"id":"E"},{"text":"Assume the more senior person's preferred layout meets both needs","why":"Authority does not make different information requirements identical.","correct":false,"id":"F"},{"text":"Produce two unrelated definitions of the same measure","why":"Shared measures can support different levels of detail without inconsistent meaning.","correct":false,"id":"G"},{"text":"Clarify the distinct decisions and urgency","why":"Authority does not make different information requirements identical.","correct":true,"id":"H"}],"answer":"Authority does not make different information requirements identical. A feasible plan needs an agreed boundary rather than unsupported commitments. Shared measures can support different levels of detail without inconsistent meaning. Documenting the compromise reduces surprises and makes later changes manageable.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q03"},{"ksb":"K9","objective":"Feasibility constraints","prompt":"The customer requests a daily report, but the authorised source is refreshed weekly. Which requirements response is justified?","options":[{"text":"Record the agreed currency and delivery expectation","why":"Currency affects whether the output is suitable for its intended use.","correct":true,"id":"A"},{"text":"Discuss whether weekly data or another approved source meets the decision","why":"An alternative needs explicit discussion and honest representation of the data.","correct":true,"id":"B"},{"text":"Assume the analyst can unilaterally change the upstream schedule","why":"A dependency needs the responsible owner's involvement and realistic authority.","correct":false,"id":"C"},{"text":"Leave refresh frequency out of the requirements","why":"Currency affects whether the output is suitable for its intended use.","correct":false,"id":"D"},{"text":"Promise daily current data because the dashboard refreshes daily","why":"Refreshing the display more frequently does not create new source observations.","correct":false,"id":"E"},{"text":"Explain the source refresh constraint","why":"Refreshing the display more frequently does not create new source observations.","correct":true,"id":"F"},{"text":"Rename weekly observations as daily estimates without agreement","why":"An alternative needs explicit discussion and honest representation of the data.","correct":false,"id":"G"},{"text":"Identify the owner of any source-change dependency","why":"A dependency needs the responsible owner's involvement and realistic authority.","correct":true,"id":"H"}],"answer":"Refreshing the display more frequently does not create new source observations. An alternative needs explicit discussion and honest representation of the data. Currency affects whether the output is suitable for its intended use. A dependency needs the responsible owner's involvement and realistic authority.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q04"},{"ksb":"K9","objective":"Confirming a measure","prompt":"Two stakeholders use 'successful cases' differently: one means closed, the other means closed within target. Which actions resolve the requirement?","options":[{"text":"Use whichever definition gives the larger successful-case count","why":"A reproducible requirement needs an agreed meaning and calculation; a preferable result cannot resolve conflicting definitions.","correct":false,"id":"A"},{"text":"Choose the definition with the larger number","why":"A meaningful choice depends on the decision, not a preferred headline.","correct":false,"id":"B"},{"text":"Ask which decision each definition supports","why":"A meaningful choice depends on the decision, not a preferred headline.","correct":true,"id":"C"},{"text":"Give both calculations the same success-rate label","why":"Different definitions need clear naming to avoid misleading comparison.","correct":false,"id":"D"},{"text":"Agree distinct labels if both measures are needed","why":"Different definitions need clear naming to avoid misleading comparison.","correct":true,"id":"E"},{"text":"Validate the agreed definition with the relevant stakeholders","why":"Shared confirmation prevents a technical implementation from silently choosing the business meaning.","correct":true,"id":"F"},{"text":"Record numerators, denominators and time windows","why":"A reproducible requirement needs an agreed meaning and calculation; a preferable result cannot resolve conflicting definitions.","correct":true,"id":"G"},{"text":"Let an undocumented formula settle the disagreement","why":"Shared confirmation prevents a technical implementation from silently choosing the business meaning.","correct":false,"id":"H"}],"answer":"A meaningful choice depends on the decision, not a preferred headline. Different definitions need clear naming to avoid misleading comparison. A reproducible requirement needs an agreed meaning and calculation; a preferable result cannot resolve conflicting definitions. Shared confirmation prevents a technical implementation from silently choosing the business meaning.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q05"},{"ksb":"K9","objective":"Scope boundaries","prompt":"A project brief covers one region. A stakeholder later asks for a national comparison with different definitions. Which requirements principles apply?","options":[{"text":"Assume geographical expansion is only a cosmetic change","why":"Broader coverage and different definitions can change data, methods and effort.","correct":false,"id":"A"},{"text":"Treat the national comparison as a scope-change proposal","why":"Broader coverage and different definitions can change data, methods and effort.","correct":true,"id":"B"},{"text":"Append national totals before checking their meaning","why":"New data needs semantic and practical assessment before integration.","correct":false,"id":"C"},{"text":"Assess data comparability and delivery impact","why":"New data needs semantic and practical assessment before integration.","correct":true,"id":"D"},{"text":"Retain the original deadline without discussing additional work","why":"Existing checks and dates may no longer fit the changed requirement.","correct":false,"id":"E"},{"text":"Reuse regional acceptance checks as proof of national comparability","why":"Existing checks and dates may no longer fit the changed requirement.","correct":false,"id":"F"},{"text":"Hide the request to avoid a difficult conversation","why":"Explicit agreement is needed to manage the change or explain non-inclusion.","correct":false,"id":"G"},{"text":"Agree revised priorities or retain the original boundary","why":"Explicit agreement is needed to manage the change or explain non-inclusion.","correct":true,"id":"H"}],"answer":"Broader coverage and different definitions can change data, methods and effort. New data needs semantic and practical assessment before integration. Explicit agreement is needed to manage the change or explain non-inclusion. Existing checks and dates may no longer fit the changed requirement.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q06"},{"ksb":"K9","objective":"Elicitation method","prompt":"Users struggle to articulate how they investigate exceptions. Which methods can help establish their actual requirements?","options":[{"text":"Rely on your private memory of several informal chats","why":"A shared record lets stakeholders correct misunderstandings and agree scope.","correct":false,"id":"A"},{"text":"Treat the first prototype as a final signed-off specification","why":"A prototype can elicit feedback rather than settle every requirement automatically.","correct":false,"id":"B"},{"text":"Confirm your understanding in a shared brief","why":"A shared record lets stakeholders correct misunderstandings and agree scope.","correct":true,"id":"C"},{"text":"Use users' satisfaction ratings as the sole description of their exception workflow","why":"Ratings do not reveal the steps, decisions and constraints of a workflow; observation and task-based discussion can uncover them.","correct":false,"id":"D"},{"text":"Treat every observed workaround as a mandatory feature without discussion","why":"Requirements need contextual validation rather than copying another audience's output or accepting every workaround uncritically.","correct":false,"id":"E"},{"text":"Infer all users' needs from one unrelated executive report","why":"Requirements need contextual validation rather than copying another audience's output or accepting every workaround uncritically.","correct":false,"id":"F"},{"text":"Use a prototype to test interpretations and missing needs","why":"A prototype can elicit feedback rather than settle every requirement automatically.","correct":true,"id":"G"},{"text":"Observe an authorised example of the current workflow","why":"Ratings do not reveal the steps, decisions and constraints of a workflow; observation and task-based discussion can uncover them.","correct":true,"id":"H"}],"answer":"Ratings do not reveal the steps, decisions and constraints of a workflow; observation and task-based discussion can uncover them. A prototype can elicit feedback rather than settle every requirement automatically. A shared record lets stakeholders correct misunderstandings and agree scope. Requirements need contextual validation rather than copying another audience's output or accepting every workaround uncritically.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q07"},{"ksb":"K9","objective":"Measurable acceptance","prompt":"A stakeholder says the report must be 'fast and easy'. Which steps turn that into usable requirements?","options":[{"text":"Agree how representative users will check ease of use","why":"Intended users and actual tasks provide stronger evidence of usability.","correct":true,"id":"A"},{"text":"Record 'fast' unchanged as a fully testable criterion","why":"A measurable task and threshold make evaluation more concrete than an undefined adjective.","correct":false,"id":"B"},{"text":"Let the developer's preference be the only usability measure","why":"Intended users and actual tasks provide stronger evidence of usability.","correct":false,"id":"C"},{"text":"Replace all acceptance criteria with a screenshot","why":"A screenshot and product reputation do not establish task performance or usability.","correct":false,"id":"D"},{"text":"Clarify the expected data volume and device context","why":"Performance expectations need a relevant usage context.","correct":true,"id":"E"},{"text":"Agree the task users must complete and acceptable response time","why":"A measurable task and threshold make evaluation more concrete than an undefined adjective.","correct":true,"id":"F"},{"text":"Assume a popular BI tool guarantees the requirement","why":"A screenshot and product reputation do not establish task performance or usability.","correct":false,"id":"G"},{"text":"Test only a tiny sample on the analyst's fastest machine","why":"Performance expectations need a relevant usage context.","correct":false,"id":"H"}],"answer":"A measurable task and threshold make evaluation more concrete than an undefined adjective. Performance expectations need a relevant usage context. Intended users and actual tasks provide stronger evidence of usability. A screenshot and product reputation do not establish task performance or usability.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q08"},{"ksb":"K9","objective":"Power and interest","prompt":"A sponsor has high power but little daily involvement. Frontline users have lower formal power and use the output every day. Which engagement choices are justified?","options":[{"text":"Use the matrix to tailor engagement rather than replace judgement","why":"A stakeholder tool supports engagement planning but does not justify disregarding affected people.","correct":true,"id":"A"},{"text":"Freeze the map regardless of changed responsibilities","why":"Power, interest and responsibilities can change during a project.","correct":false,"id":"B"},{"text":"Exclude frontline users because their formal power is lower","why":"Frequent use and practical knowledge make their needs important despite lower formal authority.","correct":false,"id":"C"},{"text":"Treat the matrix as permission to ignore affected groups","why":"A stakeholder tool supports engagement planning but does not justify disregarding affected people.","correct":false,"id":"D"},{"text":"Exclude the sponsor because they will not use every filter","why":"Decision authority can remain relevant even with limited day-to-day use.","correct":false,"id":"E"},{"text":"Involve frontline users in requirements and usability review","why":"Frequent use and practical knowledge make their needs important despite lower formal authority.","correct":true,"id":"F"},{"text":"Keep the sponsor appropriately informed about decisions and risks","why":"Decision authority can remain relevant even with limited day-to-day use.","correct":true,"id":"G"},{"text":"Review stakeholder positions when the project changes","why":"Power, interest and responsibilities can change during a project.","correct":true,"id":"H"}],"answer":"Decision authority can remain relevant even with limited day-to-day use. Frequent use and practical knowledge make their needs important despite lower formal authority. A stakeholder tool supports engagement planning but does not justify disregarding affected people. Power, interest and responsibilities can change during a project.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q09"},{"ksb":"K9","objective":"User versus requester","prompt":"The person commissioning a report will not operate it. A separate team must refresh and maintain it. Which requirements should be captured?","options":[{"text":"Agree refresh ownership and handover expectations","why":"A recurring output needs an explicit sustainable operating arrangement.","correct":true,"id":"A"},{"text":"Treat sponsor approval as a substitute for all user feedback","why":"Sponsor agreement and practical usability checks serve different purposes.","correct":false,"id":"B"},{"text":"Assume commissioning authority implies maintenance capacity","why":"Commissioning and ongoing operational responsibility can belong to different people.","correct":false,"id":"C"},{"text":"Require the support team to adopt an unapproved tool without assessment","why":"The sponsor's acceptance does not establish another team's capability or access. Capture maintainability and approved-tool requirements with the people doing that work.","correct":false,"id":"D"},{"text":"Identify the maintaining team's skills and capacity","why":"Commissioning and ongoing operational responsibility can belong to different people.","correct":true,"id":"E"},{"text":"Treat the sponsor's approval as confirmation that the maintenance team can operate the refresh","why":"The sponsor's acceptance does not establish another team's capability or access. Capture maintainability and approved-tool requirements with the people doing that work.","correct":false,"id":"F"},{"text":"Include the actual users in relevant review","why":"Sponsor agreement and practical usability checks serve different purposes.","correct":true,"id":"G"},{"text":"Leave ownership undecided until the analyst moves on","why":"A recurring output needs an explicit sustainable operating arrangement.","correct":false,"id":"H"}],"answer":"Commissioning and ongoing operational responsibility can belong to different people. A recurring output needs an explicit sustainable operating arrangement. Sponsor agreement and practical usability checks serve different purposes. The sponsor's acceptance does not establish another team's capability or access. Capture maintainability and approved-tool requirements with the people doing that work.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T19-E2-Q10"}]},{"id":"T20","title":"K10 · Combining Data Sources","description":"Grain, keys, join semantics, append operations and reconciliation.","questions":[{"ksb":"K10","objective":"Join multiplication","prompt":"Requests has 80 distinct request IDs. A left join produces 96 rows; three requests have no lookup match. Which conclusions follow?","options":[{"text":"An inner join on the same condition would have 93 rows","why":"Removing the three unmatched rows leaves 93 output rows, including any multiplied matches.","correct":true,"id":"A"},{"text":"The matched output represents 77 distinct request IDs","why":"Eighty minus three gives 77 matched request identities; row inflation alone does not identify the distribution of duplicate keys.","correct":true,"id":"B"},{"text":"The three unmatched requests remain with NULL lookup fields","why":"Preserving unmatched left rows is the relevant behaviour of this join.","correct":true,"id":"C"},{"text":"Some requests matched multiple lookup rows","why":"A left join can multiply rows when the right side contains multiple matches.","correct":true,"id":"D"},{"text":"The output proves there were 96 distinct source requests","why":"A left join can multiply rows when the right side contains multiple matches.","correct":false,"id":"E"},{"text":"The inner join must contain exactly 77 rows","why":"Removing the three unmatched rows leaves 93 output rows, including any multiplied matches.","correct":false,"id":"F"},{"text":"The extra 16 rows establish exactly 16 duplicated lookup keys","why":"Eighty minus three gives 77 matched request identities; row inflation alone does not identify the distribution of duplicate keys.","correct":false,"id":"G"},{"text":"A left join removes every unmatched request","why":"Preserving unmatched left rows is the relevant behaviour of this join.","correct":false,"id":"H"}],"answer":"A left join can multiply rows when the right side contains multiple matches. Preserving unmatched left rows is the relevant behaviour of this join. Removing the three unmatched rows leaves 93 output rows, including any multiplied matches. Eighty minus three gives 77 matched request identities; row inflation alone does not identify the distribution of duplicate keys.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q01"},{"ksb":"K10","objective":"Benefit and risk","prompt":"A repeated report replaces manual copying with an authorised, documented join and reconciliation checks. Which benefits can be claimed with suitable evidence?","options":[{"text":"Automatic correctness of any future schema change","why":"A stable rule still needs maintenance when source structure or meaning changes.","correct":false,"id":"A"},{"text":"Omit unresolved linkage issues because the workflow is automated","why":"Automation does not remove the need to disclose unresolved risks affecting interpretation.","correct":false,"id":"B"},{"text":"Explain residual unmatched or conflicting records","why":"Automation does not remove the need to disclose unresolved risks affecting interpretation.","correct":true,"id":"C"},{"text":"Proof of accuracy solely from the selected software brand","why":"Traceable methods and verification support quality more directly than brand reputation.","correct":false,"id":"D"},{"text":"Better traceability through documented transformations and checks","why":"Traceable methods and verification support quality more directly than brand reputation.","correct":true,"id":"E"},{"text":"Consistent application of the agreed matching rule","why":"A stable rule still needs maintenance when source structure or meaning changes.","correct":true,"id":"F"},{"text":"Guaranteed elimination of every future source error","why":"A repeatable process can reduce manual work without making its sources infallible.","correct":false,"id":"G"},{"text":"Reduced repeated manual handling where measured or observed","why":"A repeatable process can reduce manual work without making its sources infallible.","correct":true,"id":"H"}],"answer":"A repeatable process can reduce manual work without making its sources infallible. A stable rule still needs maintenance when source structure or meaning changes. Traceable methods and verification support quality more directly than brand reputation. Automation does not remove the need to disclose unresolved risks affecting interpretation.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q02"},{"ksb":"K10","objective":"UNION versus joins","prompt":"January and February files have compatible columns and one row per transaction. You need one combined transaction table. Which statements are correct?","options":[{"text":"Assume matching column count alone guarantees aligned meanings","why":"Retaining rows does not validate identity, and compatible structure also needs appropriate column meanings and types.","correct":false,"id":"A"},{"text":"Assume UNION ALL validates unique transaction IDs","why":"Retaining rows does not validate identity, and compatible structure also needs appropriate column meanings and types.","correct":false,"id":"B"},{"text":"An append or UNION operation stacks compatible rows","why":"Appending combines rows of the same shape; joining relates columns through matching conditions.","correct":true,"id":"C"},{"text":"Use UNION to repair every business-level duplicate automatically","why":"Exact row equality is not always the same as duplicate business identity.","correct":false,"id":"D"},{"text":"UNION preserves every duplicate result row by definition","why":"Standard UNION removes duplicate rows; UNION ALL retains them.","correct":false,"id":"E"},{"text":"A key-based join is required simply because two files exist","why":"Appending combines rows of the same shape; joining relates columns through matching conditions.","correct":false,"id":"F"},{"text":"Choose duplicate treatment according to transaction identity","why":"Exact row equality is not always the same as duplicate business identity.","correct":true,"id":"G"},{"text":"UNION removes exact duplicate result rows","why":"Standard UNION removes duplicate rows; UNION ALL retains them.","correct":true,"id":"H"}],"answer":"Appending combines rows of the same shape; joining relates columns through matching conditions. Standard UNION removes duplicate rows; UNION ALL retains them. Exact row equality is not always the same as duplicate business identity. Retaining rows does not validate identity, and compatible structure also needs appropriate column meanings and types.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q03"},{"ksb":"K10","objective":"Unit mismatch","prompt":"One source reports expenditure in pounds, another in thousands of pounds. They share project IDs. Which steps are necessary before interpreting combined totals?","options":[{"text":"Verify only that the combined table has the expected columns","why":"Structural checks alone do not validate numerical transformations.","correct":false,"id":"A"},{"text":"Infer a thousandfold increase as a genuine performance change","why":"A scale difference is not itself a real increase or evidence of different currencies.","correct":false,"id":"B"},{"text":"Add the raw values because the project IDs match","why":"Matching identities do not make differently scaled amounts directly additive.","correct":false,"id":"C"},{"text":"Infer period alignment from the amount column's name","why":"A shared label does not establish comparable time coverage or inclusion rules.","correct":false,"id":"D"},{"text":"Reconcile transformed amounts against source totals","why":"Structural checks alone do not validate numerical transformations.","correct":true,"id":"E"},{"text":"Check whether both sources cover the same period and scope","why":"A shared label does not establish comparable time coverage or inclusion rules.","correct":true,"id":"F"},{"text":"Standardise or clearly handle the amount units","why":"Matching identities do not make differently scaled amounts directly additive.","correct":true,"id":"G"},{"text":"Apply a currency conversion rate instead of the stated scale conversion","why":"A scale difference is not itself a real increase or evidence of different currencies.","correct":false,"id":"H"}],"answer":"Matching identities do not make differently scaled amounts directly additive. A shared label does not establish comparable time coverage or inclusion rules. Structural checks alone do not validate numerical transformations. A scale difference is not itself a real increase or evidence of different currencies.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q04"},{"ksb":"K10","objective":"Foreign-key meaning","prompt":"Many orders reference the same customer. Which statements about the relationship are correct?","options":[{"text":"Deduplicate orders by customer ID before calculating total order value","why":"Removing valid orders or arbitrarily choosing conflicting reference records can distort the analysis.","correct":false,"id":"A"},{"text":"Treat matching integer types as proof of referential integrity","why":"Compatible types do not show that each referenced customer exists.","correct":false,"id":"B"},{"text":"Count distinct customers separately from joined order rows","why":"A one-to-many relationship means order rows and customer entities differ.","correct":true,"id":"C"},{"text":"Report the joined order-row count as the customer count","why":"A one-to-many relationship means order rows and customer entities differ.","correct":false,"id":"D"},{"text":"Choose the first customer record when conflicting keys exist without investigation","why":"Removing valid orders or arbitrarily choosing conflicting reference records can distort the analysis.","correct":false,"id":"E"},{"text":"The customer reference must be unique in every order row","why":"Repeated customer references are expected when one customer places several orders.","correct":false,"id":"F"},{"text":"The customer table needs a suitable unique referenced key","why":"Repeated customer references are expected when one customer places several orders.","correct":true,"id":"G"},{"text":"Check for order references missing from the customer table","why":"Compatible types do not show that each referenced customer exists.","correct":true,"id":"H"}],"answer":"Repeated customer references are expected when one customer places several orders. Compatible types do not show that each referenced customer exists. A one-to-many relationship means order rows and customer entities differ. Removing valid orders or arbitrarily choosing conflicting reference records can distort the analysis.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q05"},{"ksb":"K10","objective":"Composite keys","prompt":"A reference table has one target per service and month. Service alone repeats. Which joining decisions are appropriate?","options":[{"text":"Accept the join solely because no syntax error occurred","why":"Successful execution does not establish correct key meaning or cardinality.","correct":false,"id":"A"},{"text":"Match text month names without considering year","why":"A month name alone may combine observations from different years.","correct":false,"id":"B"},{"text":"Reconcile matches and resulting counts","why":"Successful execution does not establish correct key meaning or cardinality.","correct":true,"id":"C"},{"text":"Check only whether service names are spelled correctly","why":"Correct spelling does not establish one reference row per composite key.","correct":false,"id":"D"},{"text":"Align month representations before joining","why":"A month name alone may combine observations from different years.","correct":true,"id":"E"},{"text":"Join only on service because that column exists in both tables","why":"The stated grain requires both fields to identify the relevant target.","correct":false,"id":"F"},{"text":"Use service and month as the intended matching key","why":"The stated grain requires both fields to identify the relevant target.","correct":true,"id":"G"},{"text":"Check that each service-month key is unique in the reference","why":"Correct spelling does not establish one reference row per composite key.","correct":true,"id":"H"}],"answer":"The stated grain requires both fields to identify the relevant target. Correct spelling does not establish one reference row per composite key. A month name alone may combine observations from different years. Successful execution does not establish correct key meaning or cardinality.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q06"},{"ksb":"K10","objective":"Choosing a left join","prompt":"Every request must remain in a report, including requests with no category lookup. Which design choices meet that requirement?","options":[{"text":"Label unmatched categories explicitly in the analysis","why":"An unmatched key is not evidence that the request belongs to the modal category.","correct":true,"id":"A"},{"text":"Replace every missing category with the most common category","why":"An unmatched key is not evidence that the request belongs to the modal category.","correct":false,"id":"B"},{"text":"Assume a left join cannot multiply the request rows","why":"Multiple right-side matches can still inflate the output.","correct":false,"id":"C"},{"text":"Check lookup-key uniqueness before relying on row counts","why":"Multiple right-side matches can still inflate the output.","correct":true,"id":"D"},{"text":"Start from Requests and left join the category lookup","why":"The left join retains requests without matches; the inner join would exclude them.","correct":true,"id":"E"},{"text":"Filter out NULL lookup fields after joining and claim all requests remain","why":"Such filters can remove the unmatched rows the left join was chosen to preserve.","correct":false,"id":"F"},{"text":"Start from Requests and use an inner join","why":"The left join retains requests without matches; the inner join would exclude them.","correct":false,"id":"G"},{"text":"Put a lookup-only condition in WHERE without checking its effect on unmatched rows","why":"Such filters can remove the unmatched rows the left join was chosen to preserve.","correct":false,"id":"H"}],"answer":"The left join retains requests without matches; the inner join would exclude them. Multiple right-side matches can still inflate the output. An unmatched key is not evidence that the request belongs to the modal category. Such filters can remove the unmatched rows the left join was chosen to preserve.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q07"},{"ksb":"K10","objective":"NULL join keys","prompt":"Some requests have NULL service IDs. An SQL equality join uses Requests.service_id = Services.service_id. Which statements are justified?","options":[{"text":"Count and explain unmatched records after combination","why":"A query can execute while leaving many records unmatched.","correct":true,"id":"A"},{"text":"Ordinary equality does not make NULL match NULL","why":"NULL is not a known shared identifier under ordinary SQL equality semantics.","correct":true,"id":"B"},{"text":"Use an inner join and describe the result as every request","why":"An inner join excludes records without a matching key.","correct":false,"id":"C"},{"text":"Investigate why the request keys are missing","why":"A missing key provides no basis for assigning a particular service.","correct":true,"id":"D"},{"text":"Replace every NULL with a popular service ID","why":"A missing key provides no basis for assigning a particular service.","correct":false,"id":"E"},{"text":"Preserve unmatched requests if the analytical requirement needs them","why":"An inner join excludes records without a matching key.","correct":true,"id":"F"},{"text":"Two NULL keys automatically represent the same service","why":"NULL is not a known shared identifier under ordinary SQL equality semantics.","correct":false,"id":"G"},{"text":"Treat successful execution as proof of complete linkage","why":"A query can execute while leaving many records unmatched.","correct":false,"id":"H"}],"answer":"NULL is not a known shared identifier under ordinary SQL equality semantics. A missing key provides no basis for assigning a particular service. An inner join excludes records without a matching key. A query can execute while leaving many records unmatched.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q08"},{"ksb":"K10","objective":"Right join equivalence","prompt":"A report must retain every service, including services with no requests. Which equivalent designs and interpretations are correct?","options":[{"text":"Services LEFT JOIN Requests can retain every service","why":"An inner join omits services with no match.","correct":true,"id":"A"},{"text":"Interpret NULL request fields as one zero-duration request","why":"An outer-join placeholder is not an actual request, and removing it loses unused services.","correct":false,"id":"B"},{"text":"Requests RIGHT JOIN Services can express the same preservation","why":"Reversing the preserved side changes which unmatched records survive.","correct":true,"id":"C"},{"text":"Count a suitable request identifier when counting requests per service","why":"The retained outer-join row can make COUNT(*) equal one even when there is no request.","correct":true,"id":"D"},{"text":"Remove unmatched services and still call the report complete service coverage","why":"An outer-join placeholder is not an actual request, and removing it loses unused services.","correct":false,"id":"E"},{"text":"Use COUNT(*) as the request count for an unmatched service row","why":"The retained outer-join row can make COUNT(*) equal one even when there is no request.","correct":false,"id":"F"},{"text":"Requests LEFT JOIN Services preserves every unused service","why":"Reversing the preserved side changes which unmatched records survive.","correct":false,"id":"G"},{"text":"Services INNER JOIN Requests retains services without requests","why":"An inner join omits services with no match.","correct":false,"id":"H"}],"answer":"An inner join omits services with no match. Reversing the preserved side changes which unmatched records survive. The retained outer-join row can make COUNT(*) equal one even when there is no request. An outer-join placeholder is not an actual request, and removing it loses unused services.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q09"},{"ksb":"K10","objective":"Full outer comparison","prompt":"You need to reconcile IDs in two systems and see matched, left-only and right-only records. Which approach supports that purpose?","options":[{"text":"A full outer join can retain all three groups","why":"An inner join contains matches and omits unmatched records from either side.","correct":true,"id":"A"},{"text":"Treat every NULL in any non-key field as an unmatched record","why":"A matched row can still contain a missing non-key value.","correct":false,"id":"B"},{"text":"Distinguish unmatched groups using the presence of each side's key","why":"A matched row can still contain a missing non-key value.","correct":true,"id":"C"},{"text":"Explain differences in system coverage and extraction times","why":"Unmatched records can arise from legitimate scope or timing differences as well as errors.","correct":true,"id":"D"},{"text":"Check key uniqueness before interpreting reconciliation counts","why":"Duplicate matching keys can create multiple output rows for an entity.","correct":true,"id":"E"},{"text":"Assume one output row always equals one reconciled entity","why":"Duplicate matching keys can create multiple output rows for an entity.","correct":false,"id":"F"},{"text":"Attribute every unmatched ID to a data-entry error immediately","why":"Unmatched records can arise from legitimate scope or timing differences as well as errors.","correct":false,"id":"G"},{"text":"An inner join alone exposes both unmatched groups","why":"An inner join contains matches and omits unmatched records from either side.","correct":false,"id":"H"}],"answer":"An inner join contains matches and omits unmatched records from either side. A matched row can still contain a missing non-key value. Duplicate matching keys can create multiple output rows for an entity. Unmatched records can arise from legitimate scope or timing differences as well as errors.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T20-E2-Q10"}]}]);d.revisedPackSha256["revised-1"]="e4c7fb04efc8fc624ca9eb2a23b514d9e6e9156b4e4b7b603f054459556096e1";})();
